-- Migration 042: Informatics 8th grade - the 8 lessons of Chapter 3 "Spreadsheets" (kk/ru/en, picture tasks with a marking scheme). Replaces the lessons of 039 in place (same module, same positions).
-- GENERATED by scripts/gen-sheetslab-sql.mjs from src/lessons/sheetsLab: edit the TypeScript, then regenerate.
-- Needs 041_sheet_criteria.sql. Idempotent: lessons are matched by module position (or title), so old sessions keep their lesson.

do $sheets_lab$
declare
  v_school uuid; v_owner uuid; v_course uuid; v_module uuid; v_lesson uuid; v_spec record;
begin
  select p.school_id, p.id into v_school, v_owner from public.profiles p
  where p.role in ('teacher', 'admin') order by p.created_at limit 1;
  if v_owner is null then raise exception 'Мұғалім немесе әкімші аккаунты табылмады'; end if;
  -- the lessons belong to whoever owns the 8th-grade course, so they show in that teacher's own library
  select c.owner_id, c.school_id into v_owner, v_school from public.cf_curr_courses c
  where c.title in ('Informatics 8th grade', 'Информатика 8-сынып', 'Информатика 8') order by c.created_at limit 1;
  if v_owner is null then select p.school_id, p.id into v_school, v_owner from public.profiles p where p.role in ('teacher', 'admin') order by p.created_at limit 1; end if;

  select id into v_course from public.cf_curr_courses
  where title in ('Informatics 8th grade', 'Информатика 8-сынып', 'Информатика 8') and school_id = v_school limit 1;
  if v_course is null then
    insert into public.cf_curr_courses (school_id, owner_id, title, subject, grade)
    values (v_school, v_owner, 'Informatics 8th grade', 'Информатика', 8) returning id into v_course;
  end if;

  select id into v_module from public.cf_curr_modules where course_id = v_course and title in ($sl$Электрондық кестелер (3-тарау)$sl$, 'Электрондық кестелер: практикум') order by (title = $sl$Электрондық кестелер (3-тарау)$sl$) desc limit 1;
  if v_module is not null then update public.cf_curr_modules set title = $sl$Электрондық кестелер (3-тарау)$sl$ where id = v_module; end if;
  if v_module is null then
    insert into public.cf_curr_modules (course_id, title, position, kind, quarter, grade)
    values (v_course, $sl$Электрондық кестелер (3-тарау)$sl$, 1, 'lesson', 2, 8) returning id into v_module;
  end if;

  for v_spec in select * from (values
    ($sl$3.1 Статистикалық деректер$sl$, $sl$Информатика$sl$, 0, $sl${"summary":"Сілтеме түрлері: салыстырмалы және абсолютті сілтеме. Формуланы көшіргенде сілтеме қалай өзгеретінін және $ белгісін қолдануды үйрену.","objectives":["Сілтеменің түрлерін білу","Кестеде абсолютті және салыстырмалы сілтемені қолдану"],"grade":8,"duration":"45 минут","ru":{"summary":"Виды ссылок: относительные и абсолютные. Как меняются ссылки при копировании формулы и как использовать знак $.","objectives":["Знать виды ссылок","Применять абсолютные и относительные ссылки в таблице"]},"en":{"summary":"Types of cell references: relative and absolute. How references change when a formula is copied and how to use the $ sign.","objectives":["Learn the types of cell references","Use absolute and relative references in the spreadsheet"]}}$sl$::jsonb, $sl$[{"term":"reference","definition":"сілтеме — формуладағы ұяшықтың мекенжайы, мысалы B2 · ссылка — адрес ячейки в формуле, например B2 · reference — the address of a cell in a formula, e.g. B2"},{"term":"relative","definition":"салыстырмалы — көшіргенде өзгереді (A2) · относительный — меняется при копировании (A2) · relative — changes when copied (A2)"},{"term":"absolute","definition":"абсолютті — көшіргенде өзгермейді ($A$2) · абсолютный — не меняется при копировании ($A$2) · absolute — does not change when copied ($A$2)"},{"term":"designated","definition":"тағайындалған — доллар белгісімен ($) белгіленген · назначенный — обозначенный знаком доллара ($) · designated — marked with the dollar sign ($)"},{"term":"convenient","definition":"қолайлы — жұмысқа ыңғайлы · удобный — удобный в работе · convenient — easy and handy to use"},{"term":"depending on","definition":"байланысты — бір нәрсеге қарай өзгеретін · в зависимости от — меняется по чему-то · depending on — changing according to something"}]$sl$::jsonb, $sl$[{"type":"title","pageType":"slide","templateId":"title","title":"3.1 Статистикалық деректер","subtitle":"Информатика 8-сынып · 3-тарау «Электрондық кестелер»","ru":{"title":"3.1 Статистические данные","subtitle":"Информатика 8 класс · глава 3 «Электронные таблицы»"},"en":{"title":"3.1 Statistical data","subtitle":"Informatics Grade 8 · Chapter 3 “Spreadsheets”"},"design":"lab"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"Сен не үйренесің","bullets":["Сілтеменің түрлерін үйренесің.","Кестеде абсолютті және салыстырмалы сілтемені қолданасың.","Сұрақ: шығындарыңды жазып отырасың ба? Қандай қолданба немесе әдіс қолданасың?"],"notes":"Сыныптан сұраңыз: «Шығынды қайда жазасыңдар — қолданба, дәптер, кесте?» Кестеде бір формуланы жазып, барлық жолға көшіруге болатынын айтып, тақырыпқа өтіңіз.","ru":{"title":"Что ты узнаешь","bullets":["Узнаешь, какие бывают ссылки на ячейки.","Будешь применять абсолютные и относительные ссылки в таблице.","Вопрос: ты записываешь свои расходы? Какими приложениями или способами пользуешься?"],"notes":"Спросите класс: «Где вы записываете расходы — приложение, тетрадь, таблица?» Скажите, что в таблице формулу можно записать один раз и скопировать на все строки."},"en":{"title":"You will","bullets":["Learn types of cell references.","Use absolute and relative references in the spreadsheet.","Question: do you track your expenses? Which apps or methods do you use?"],"notes":"Ask the class: “Where do you track expenses — an app, a notebook, a spreadsheet?” Point out that a sheet lets you write a formula once and copy it to every row."},"design":"lab"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"Қайталау: жол мен баған","bullets":["Баған (Column) — тігінен орналасқан ұяшықтар. Әріппен белгіленеді: A, B, C…","Жол (Row) — көлденең орналасқан ұяшықтар. Санмен белгіленеді: 1, 2, 3…","Ұяшық мекенжайы = баған әрпі + жол нөмірі. C4 — C бағаны мен 4-жолдың қиылысы.","Аралық: B2:B6 — бір бағанда, B2:D2 — бір жолда. Формуланы көшіргенде әріп (баған) немесе сан (жол) ауысады — келесі слайдтарда соны көреміз."],"notes":"Сыныпқа сұрақ: «C4 қайда тұр?», «B2:B6 қанша ұяшық?» (5). Содан кейін сілтемелерге өтіңіз.","art":"anatomy","ru":{"title":"Повторение: строка и столбец","bullets":["Столбец (Column) — ячейки по вертикали. Обозначается буквой: A, B, C…","Строка (Row) — ячейки по горизонтали. Обозначается числом: 1, 2, 3…","Адрес ячейки = буква столбца + номер строки. C4 — пересечение столбца C и строки 4.","Диапазон: B2:B6 — в одном столбце, B2:D2 — в одной строке. При копировании формулы меняется буква (столбец) или число (строка) — это мы увидим дальше."],"notes":"Вопрос классу: «Где находится C4?», «Сколько ячеек в B2:B6?» (5). Затем переходите к ссылкам."},"en":{"title":"Review: row and column","bullets":["A column (Column) runs vertically. It is named by a letter: A, B, C…","A row (Row) runs horizontally. It is named by a number: 1, 2, 3…","A cell address = column letter + row number. C4 is where column C meets row 4.","A range: B2:B6 is in one column, B2:D2 in one row. When a formula is copied, the letter (column) or the number (row) shifts — we will see that next."],"notes":"Ask the class: “Where is C4?”, “How many cells are in B2:B6?” (5). Then move on to references."},"design":"lab"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"Салыстырмалы және абсолютті сілтеме","bullets":["Сілтеменің екі түрі бар: салыстырмалы және абсолютті. Формуланы басқа ұяшыққа көшіргенде олар әртүрлі жүреді.","Салыстырмалы сілтеме формуланы көшіргенде өзгереді. Әдепкіде барлық сілтеме салыстырмалы.","Абсолютті сілтеме жолды және/немесе бағанды тұрақты ұстайды. Ол формулада доллар белгісімен ($) белгіленеді."],"art":"refs","ru":{"title":"Относительные и абсолютные ссылки","bullets":["Бывает два вида ссылок: относительные и абсолютные. При копировании формулы в другие ячейки они ведут себя по-разному.","Относительные ссылки меняются при копировании формулы. По умолчанию все ссылки относительные.","Абсолютная ссылка закрепляет строку и/или столбец. В формуле она обозначается знаком доллара ($)."]},"en":{"title":"Relative and absolute values","bullets":["There are two types of cell references: relative and absolute. They behave differently when copied and filled to other cells.","Relative references change when a formula is copied to another cell. By default, all cell references are relative.","An absolute reference keeps a row and/or column constant. It is designated in the formula by a dollar sign ($)."]},"design":"lab"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"Сілтеме жазылымдары","bullets":["A2 — көшіргенде баған да, жол да өзгереді.","$A$2 — көшіргенде баған да, жол да өзгермейді. Ең жиі осы түрі қолданылады.","A$2 — жол өзгермейді. $A2 — баған өзгермейді. Бұл екеуі сирек қолданылады."],"code":"A2      column and row change\n$A$2    column and row stay\nA$2     row stays\n$A2     column stays","lang":"text","ru":{"title":"Виды записи ссылки","bullets":["A2 — при копировании меняются и столбец, и строка.","$A$2 — не меняются ни столбец, ни строка. Чаще всего используют именно такую запись.","A$2 — строка не меняется. $A2 — столбец не меняется. Эти два вида нужны реже."]},"en":{"title":"Reference formats","bullets":["A2 — the column and the row change when copied.","$A$2 — the column and the row do not change when copied. You will use this one most often.","A$2 — the row does not change. $A2 — the column does not change. These two are used much less often."]},"design":"lab"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"Салыстырмалы сілтеме","bullets":["Әдепкіде барлық сілтеме салыстырмалы: көшіргенде жолдар мен бағандардың орнына қарай өзгереді.","Мысалы, =A1+B1 формуласын 1-жолдан 2-жолға көшірсең, ол =A2+B2 болады.","Бірдей есепті көп жолда қайталау керек болғанда салыстырмалы сілтеме өте қолайлы."],"code":"=A1+B1   (row 1)\n=A2+B2   (row 2)\n=A3+B3   (row 3)","lang":"text","art":"copy","ru":{"title":"Относительные ссылки","bullets":["По умолчанию все ссылки относительные: при копировании они меняются в зависимости от положения строк и столбцов.","Например, если скопировать формулу =A1+B1 из строки 1 в строку 2, она станет =A2+B2.","Относительные ссылки удобны, когда одно и то же вычисление нужно повторить в нескольких строках или столбцах."]},"en":{"title":"Relative references","bullets":["By default all references are relative: when copied they change based on the relative position of rows and columns.","For example, if you copy =A1+B1 from row 1 to row 2, the formula becomes =A2+B2.","Relative references are especially convenient when you repeat the same calculation across rows or columns."]},"design":"lab"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"Абсолютті сілтеме","bullets":["Кейде формуланы көшіргенде сілтеме өзгермеуі керек (салық мөлшері, жеңілдік). Ондай ұяшықты абсолютті сілтемемен бекітеміз.","$E$1 деп жазамыз: баған әрпі мен жол нөмірінің алдына $ қоямыз.","Мысалы, =B3*C3*$E$1 формуласында E1 әрқашан бір ұяшық, ал B3 мен C3 жолмен бірге жылжиды."],"code":"=B3*C3*$E$1\n=B4*C4*$E$1\n=B5*C5*$E$1","lang":"text","ru":{"title":"Абсолютные ссылки","bullets":["Иногда при копировании ссылка не должна меняться (ставка налога, скидка). Такую ячейку закрепляют абсолютной ссылкой.","Записываем $E$1: знак $ ставим перед буквой столбца и перед номером строки.","Например, в формуле =B3*C3*$E$1 ячейка E1 всегда одна и та же, а B3 и C3 сдвигаются вместе со строкой."]},"en":{"title":"Absolute references","bullets":["Sometimes you do not want a reference to change when copying (a tax rate, a discount). Use an absolute reference for that cell.","Write $E$1: put $ before the column letter and before the row number.","For example, in =B3*C3*$E$1 the cell E1 is always the same, while B3 and C3 move with the row."]},"design":"lab"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"example","title":"Кестемен түсіндіру","bullets":["D4 ұяшығына =B4*C4 жаз, D8-ге дейін төмен тарт. B мен C жолмен бірге ауысады — бұл салыстырмалы сілтеме.","E4 ұяшығына =D4*$B$1 жаз, төмен тарт. $B$1 бәрінде бірдей қалады — бұл абсолютті сілтеме. E5 ішіне қарап көр.","Салыстыр: E4-ке =D4*B1 ($-сыз) жазып төмен тартсаң, E5-те B2 шығады да, нәтиже бұрмаланады.","F4: =D4+E4, төмен тарт. Содан соң D9, E9, F9 ұяшықтарына =SUM(...) жаз.","Көбейту кестесі: B13-ке =$A13*B$12 жаз, оңға, сосын төмен тарт. $A13 — баған, B$12 — жол бекіген."],"demoSheet":{"rows":18,"cols":7,"cells":{"A1":"Салық мөлшері","B1":"10%","A3":"Тауар","B3":"Бағасы, ₸","C3":"Саны","D3":"Құны","E3":"Салық","F3":"Төлем","A4":"Дәптер","B4":"150","C4":"10","A5":"Қалам","B5":"80","C5":"20","A6":"Өшіргіш","B6":"60","C6":"15","A7":"Сызғыш","B7":"120","C7":"8","A8":"Маркер","B8":"250","C8":"5","A9":"Барлығы","A11":"Көбейту кестесі","B12":"1","C12":"2","D12":"3","E12":"4","F12":"5","A13":"1","A14":"2","A15":"3","A16":"4","A17":"5"},"fmt":{"A1":{"b":1},"B1":{"nf":"pct","b":1,"bg":"#7c2d12"},"A11":{"b":1},"A3":{"b":1,"bg":"#1e3a8a"},"B3":{"b":1,"bg":"#1e3a8a"},"C3":{"b":1,"bg":"#1e3a8a"},"D3":{"b":1,"bg":"#1e3a8a"},"E3":{"b":1,"bg":"#1e3a8a"},"F3":{"b":1,"bg":"#1e3a8a"},"A9":{"b":1,"bg":"#1e3a8a"},"B12":{"b":1,"bg":"#4c1d95"},"C12":{"b":1,"bg":"#4c1d95"},"D12":{"b":1,"bg":"#4c1d95"},"E12":{"b":1,"bg":"#4c1d95"},"F12":{"b":1,"bg":"#4c1d95"},"A13":{"b":1,"bg":"#4c1d95"},"A14":{"b":1,"bg":"#4c1d95"},"A15":{"b":1,"bg":"#4c1d95"},"A16":{"b":1,"bg":"#4c1d95"},"A17":{"b":1,"bg":"#4c1d95"}}},"notes":"Мұғалімге: кесте дайын, тек формулаларды өзің жазасың. Тақтада кестені өңдеуге болады, оқушылар экранда көреді. «Бастапқыға қайтару» батырмасы кестені алғашқы күйіне келтіреді.\nКүтілетін нәтиже: D4:D8 = 1500, 1600, 900, 960, 1250 (D9 = 6210); E4:E8 = 150, 160, 90, 96, 125 (E9 = 621); F4:F8 = 1650, 1760, 990, 1056, 1375 (F9 = 6831). Көбейту кестесінде B13:F17 — 1-ден 25-ке дейінгі көбейтінділер.","ru":{"title":"Объясняем на таблице","bullets":["В D4 запиши =B4*C4 и протяни до D8. B и C сдвигаются вместе со строкой — это относительные ссылки.","В E4 запиши =D4*$B$1 и протяни вниз. $B$1 везде одинакова — это абсолютная ссылка. Загляни в E5.","Сравни: если в E4 записать =D4*B1 (без $) и протянуть, в E5 появится B2 и результат будет неверным.","F4: =D4+E4, протяни вниз. Затем в D9, E9, F9 запиши =SUM(...).","Таблица умножения: в B13 запиши =$A13*B$12, протяни вправо и вниз. $A13 — закреплён столбец, B$12 — строка."],"demoSheet":{"rows":18,"cols":7,"cells":{"A1":"Ставка налога","B1":"10%","A3":"Товар","B3":"Цена, ₸","C3":"Кол-во","D3":"Стоимость","E3":"Налог","F3":"К оплате","A4":"Тетрадь","B4":"150","C4":"10","A5":"Ручка","B5":"80","C5":"20","A6":"Ластик","B6":"60","C6":"15","A7":"Линейка","B7":"120","C7":"8","A8":"Маркер","B8":"250","C8":"5","A9":"Итого","A11":"Таблица умножения","B12":"1","C12":"2","D12":"3","E12":"4","F12":"5","A13":"1","A14":"2","A15":"3","A16":"4","A17":"5"},"fmt":{"A1":{"b":1},"B1":{"nf":"pct","b":1,"bg":"#7c2d12"},"A11":{"b":1},"A3":{"b":1,"bg":"#1e3a8a"},"B3":{"b":1,"bg":"#1e3a8a"},"C3":{"b":1,"bg":"#1e3a8a"},"D3":{"b":1,"bg":"#1e3a8a"},"E3":{"b":1,"bg":"#1e3a8a"},"F3":{"b":1,"bg":"#1e3a8a"},"A9":{"b":1,"bg":"#1e3a8a"},"B12":{"b":1,"bg":"#4c1d95"},"C12":{"b":1,"bg":"#4c1d95"},"D12":{"b":1,"bg":"#4c1d95"},"E12":{"b":1,"bg":"#4c1d95"},"F12":{"b":1,"bg":"#4c1d95"},"A13":{"b":1,"bg":"#4c1d95"},"A14":{"b":1,"bg":"#4c1d95"},"A15":{"b":1,"bg":"#4c1d95"},"A16":{"b":1,"bg":"#4c1d95"},"A17":{"b":1,"bg":"#4c1d95"}}},"notes":"Учителю: таблица готова, формулы вводите вы. На доске её можно редактировать, ученики смотрят на экран. Кнопка «Сбросить» возвращает исходное состояние.\nОжидаемый результат: D4:D8 = 1500, 1600, 900, 960, 1250 (D9 = 6210); E4:E8 = 150, 160, 90, 96, 125 (E9 = 621); F4:F8 = 1650, 1760, 990, 1056, 1375 (F9 = 6831). В таблице умножения B13:F17 — произведения от 1 до 25."},"en":{"title":"Let us see it in a sheet","bullets":["In D4 type =B4*C4 and drag down to D8. B and C move with the row — these are relative references.","In E4 type =D4*$B$1 and drag down. $B$1 stays the same everywhere — an absolute reference. Look inside E5.","Compare: if E4 is =D4*B1 (no $) and you drag down, E5 gets B2 and the result is wrong.","F4: =D4+E4, drag down. Then type =SUM(...) in D9, E9, F9.","Multiplication table: in B13 type =$A13*B$12, drag right then down. $A13 pins the column, B$12 pins the row."],"demoSheet":{"rows":18,"cols":7,"cells":{"A1":"Tax rate","B1":"10%","A3":"Item","B3":"Price, ₸","C3":"Qty","D3":"Cost","E3":"Tax","F3":"To pay","A4":"Notebook","B4":"150","C4":"10","A5":"Pen","B5":"80","C5":"20","A6":"Eraser","B6":"60","C6":"15","A7":"Ruler","B7":"120","C7":"8","A8":"Marker","B8":"250","C8":"5","A9":"Total","A11":"Multiplication table","B12":"1","C12":"2","D12":"3","E12":"4","F12":"5","A13":"1","A14":"2","A15":"3","A16":"4","A17":"5"},"fmt":{"A1":{"b":1},"B1":{"nf":"pct","b":1,"bg":"#7c2d12"},"A11":{"b":1},"A3":{"b":1,"bg":"#1e3a8a"},"B3":{"b":1,"bg":"#1e3a8a"},"C3":{"b":1,"bg":"#1e3a8a"},"D3":{"b":1,"bg":"#1e3a8a"},"E3":{"b":1,"bg":"#1e3a8a"},"F3":{"b":1,"bg":"#1e3a8a"},"A9":{"b":1,"bg":"#1e3a8a"},"B12":{"b":1,"bg":"#4c1d95"},"C12":{"b":1,"bg":"#4c1d95"},"D12":{"b":1,"bg":"#4c1d95"},"E12":{"b":1,"bg":"#4c1d95"},"F12":{"b":1,"bg":"#4c1d95"},"A13":{"b":1,"bg":"#4c1d95"},"A14":{"b":1,"bg":"#4c1d95"},"A15":{"b":1,"bg":"#4c1d95"},"A16":{"b":1,"bg":"#4c1d95"},"A17":{"b":1,"bg":"#4c1d95"}}},"notes":"For the teacher: the table is ready, you type the formulas. It is editable on the board while the class watches the screen. The Reset button restores the starting table.\nExpected: D4:D8 = 1500, 1600, 900, 960, 1250 (D9 = 6210); E4:E8 = 150, 160, 90, 96, 125 (E9 = 621); F4:F8 = 1650, 1760, 990, 1056, 1375 (F9 = 6831). In the multiplication table B13:F17 hold the products 1 to 25."}},{"type":"solution","pageType":"slide","templateId":"worked-example","kind":"exampletask","title":"Мысал: салық","sections":[{"h":"Шарты","text":"B2:B4 ұяшықтарында бағалар: 1000, 500, 800; C2:C4 ұяшықтарында саны: 2, 4, 1; E1 ұяшығында салық мөлшері 10%. Әр жолдың салығын тап."},{"h":"Алгоритм (қадамдар)","bullets":["D2 ұяшығына =B2*C2*$E$1 жаз. Нәтиже: 1000·2·0,1 = 200.","D2-ні D4-ке дейін көшір: D3 = B3*C3*$E$1, D4 = B4*C4*$E$1.","Тексер: $E$1 барлық жолда бірдей, B және C жолмен бірге өзгерді."]},{"h":"Шешімі","text":"Салықтар: 200, 200, 80.","hide":true}],"ru":{"title":"Пример: налог","sections":[{"h":"Условие","text":"В B2:B4 цены: 1000, 500, 800; в C2:C4 количество: 2, 4, 1; в E1 ставка налога 10%. Найди налог для каждой строки."},{"h":"Алгоритм (шаги)","bullets":["В D2 запиши =B2*C2*$E$1. Результат: 1000·2·0,1 = 200.","Скопируй D2 до D4: D3 = B3*C3*$E$1, D4 = B4*C4*$E$1.","Проверь: $E$1 одинакова во всех строках, а B и C изменились вместе со строкой."]},{"h":"Решение","text":"Налоги: 200, 200, 80.","hide":true}]},"en":{"title":"Example: tax","sections":[{"h":"Task","text":"B2:B4 hold prices 1000, 500, 800; C2:C4 hold quantities 2, 4, 1; E1 holds a tax rate of 10%. Find the tax for each row."},{"h":"Steps","bullets":["In D2 type =B2*C2*$E$1. Result: 1000·2·0.1 = 200.","Copy D2 down to D4: D3 = B3*C3*$E$1, D4 = B4*C4*$E$1.","Check: $E$1 is the same in every row while B and C changed with the row."]},{"h":"Solution","text":"Taxes: 200, 200, 80.","hide":true}]},"design":"lab"},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Сілтемені көшіру","prompt":"D2 ұяшығындағы =B2*$E$1 формуласын D3 ұяшығына көшірсек, қандай формула шығады?","options":["=B3*$E$1","=B3*$E$2","=B2*$E$1","=B3*E1"],"answer":0,"explanation":"B2 салыстырмалы, сондықтан B3 болады. $E$1 абсолютті, сондықтан өзгермейді.","points":1,"ru":{"title":"Копирование ссылки","prompt":"Какая формула получится, если скопировать =B2*$E$1 из D2 в D3?","options":["=B3*$E$1","=B3*$E$2","=B2*$E$1","=B3*E1"],"explanation":"B2 относительная, поэтому станет B3. $E$1 абсолютная, поэтому не изменится."},"en":{"title":"Copying a reference","prompt":"Which formula appears if =B2*$E$1 is copied from D2 to D3?","options":["=B3*$E$1","=B3*$E$2","=B2*$E$1","=B3*E1"],"explanation":"B2 is relative so it becomes B3. $E$1 is absolute so it stays."}},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Жолды бекіту","prompt":"Қай жазылым көшіргенде тек жолды тұрақты қалдырады?","options":["A2","$A$2","A$2","$A2"],"answer":2,"explanation":"$ жолдың нөмірінің алдында тұр (A$2), сондықтан тек жол өзгермейді.","points":1,"ru":{"title":"Закрепить строку","prompt":"Какая запись при копировании закрепляет только строку?","options":["A2","$A$2","A$2","$A2"],"explanation":"$ стоит перед номером строки (A$2), поэтому не меняется только строка."},"en":{"title":"Fixing the row","prompt":"Which format keeps only the row constant when copied?","options":["A2","$A$2","A$2","$A2"],"explanation":"The $ is before the row number (A$2), so only the row stays."}},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"Практикада қолданылатын формулалар","bullets":["1-практика: =B2*C2 — құны (D2-ден D6-ға көшіреміз). =SUM(D2:D6) — жалпы сома.","2-практика: =B3*C3*$E$1 — салық ($E$1 бекітілген). =B3*C3+D3 — құн мен салық қосындысы. =SUM(E3:E7) — жалпы.","3-практика: =B3*C3*$E$1 — үнемдеген сома (жеңілдік). =B3*C3-D3 — жеңілдікпен төлем. =SUM(E3:E8) — жалпы."],"code":"P1  D2: =B2*C2        D7: =SUM(D2:D6)\nP2  D3: =B3*C3*$E$1   E3: =B3*C3+D3   E8: =SUM(E3:E7)\nP3  D3: =B3*C3*$E$1   E3: =B3*C3-D3   E9: =SUM(E3:E8)","lang":"text","ru":{"title":"Формулы, которые понадобятся в практике","bullets":["Практика 1: =B2*C2 — стоимость (копируем из D2 до D6). =SUM(D2:D6) — общая сумма.","Практика 2: =B3*C3*$E$1 — налог ($E$1 закреплена). =B3*C3+D3 — стоимость с налогом. =SUM(E3:E7) — итого.","Практика 3: =B3*C3*$E$1 — сколько сэкономили (скидка). =B3*C3-D3 — оплата со скидкой. =SUM(E3:E8) — итого."]},"en":{"title":"Formulas you will use in the practice","bullets":["Practice 1: =B2*C2 — the cost (copy D2 down to D6). =SUM(D2:D6) — the total.","Practice 2: =B3*C3*$E$1 — the tax ($E$1 is pinned). =B3*C3+D3 — cost plus tax. =SUM(E3:E7) — the total.","Practice 3: =B3*C3*$E$1 — how much is saved (discount). =B3*C3-D3 — pay with the discount. =SUM(E3:E8) — the total."]},"design":"lab"},{"type":"task","pageType":"interactive","templateId":"short-answer","kind":"practice","title":"1-практика: мәзір құны","prompt":"Суреттегі кестені енгіз. D2 ұяшығына =B2*C2 жазып, формуланы D3:D6 ұяшықтарына көшір. D7-ге жалпы соманы тап.","points":7,"picture":"lec/inf8-t31a-kk.svg","pictureAlt":"Бес тағам: баға мен саны, құн мен жалпы сомаға арналған бос ұяшықтар","sheet":{"rows":14,"cols":8},"criteria":[{"id":"c1","text":"Деректер енгізілген: B2 = 2700 және C6 = 20","cell":"C6","points":1,"accept":["20"]},{"id":"c2","text":"D2 — кебабтың құны (формуламен)","cell":"D2","points":1,"formula":true,"accept":["27000"]},{"id":"c3","text":"D3 — көшірілген формула (салыстырмалы сілтеме)","cell":"D3","points":1,"formula":true,"accept":["16500"]},{"id":"c4","text":"D5 — лимонадтың құны (формуламен)","cell":"D5","points":1,"formula":true,"accept":["8000"]},{"id":"c5","text":"D6 — айранның құны (формуламен)","cell":"D6","points":1,"formula":true,"accept":["24000"]},{"id":"c6","text":"D7 — жалпы сома (SUM)","cell":"D7","points":2,"fn":"SUM","accept":["99500"]}],"steps":["Кестені тордағы A1:C6 ұяшықтарына көшір.","D2 ұяшығын таңдап, =B2*C2 жаз.","Формуланы D3:D6 ұяшықтарына көшір: сілтемелер әр жолда басқаша болуы керек.","D7 ұяшығында SUM арқылы жалпы соманы тап."],"ru":{"title":"Практика 1: стоимость меню","prompt":"Введи таблицу с рисунка. В D2 запиши =B2*C2 и скопируй формулу в D3:D6. В D7 найди общую сумму.","picture":"lec/inf8-t31a-ru.svg","pictureAlt":"Пять позиций меню: цена и количество, пустые ячейки для стоимости и итога","criteria":[{"id":"c1","text":"Данные введены: B2 = 2700 и C6 = 20","cell":"C6","points":1},{"id":"c2","text":"D2 — стоимость кебаба (формулой)","cell":"D2","points":1,"formula":true},{"id":"c3","text":"D3 — скопированная формула (относительные ссылки)","cell":"D3","points":1,"formula":true},{"id":"c4","text":"D5 — стоимость лимонада (формулой)","cell":"D5","points":1,"formula":true},{"id":"c5","text":"D6 — стоимость айрана (формулой)","cell":"D6","points":1,"formula":true},{"id":"c6","text":"D7 — общая сумма (SUM)","cell":"D7","points":2,"fn":"SUM"}],"steps":["Перенеси таблицу в ячейки A1:C6.","Выбери D2 и запиши =B2*C2.","Скопируй формулу в D3:D6: ссылки в каждой строке должны быть разными.","В D7 найди общую сумму функцией SUM."]},"en":{"title":"Practice 1: menu cost","prompt":"Enter the table from the picture. In D2 type =B2*C2 and copy the formula to D3:D6. Find the total in D7.","picture":"lec/inf8-t31a-en.svg","pictureAlt":"Five menu items with price and quantity and empty cells for the cost and the total","criteria":[{"id":"c1","text":"Data entered: B2 = 2700 and C6 = 20","cell":"C6","points":1},{"id":"c2","text":"D2 — cost of the beef kebab (formula)","cell":"D2","points":1,"formula":true},{"id":"c3","text":"D3 — the copied formula (relative references)","cell":"D3","points":1,"formula":true},{"id":"c4","text":"D5 — cost of the lemonade (formula)","cell":"D5","points":1,"formula":true},{"id":"c5","text":"D6 — cost of the ayran (formula)","cell":"D6","points":1,"formula":true},{"id":"c6","text":"D7 — the total (SUM)","cell":"D7","points":2,"fn":"SUM"}],"steps":["Copy the table into cells A1:C6.","Select D2 and type =B2*C2.","Copy the formula to D3:D6: the references must differ in each row.","In D7 find the total with SUM."]}},{"type":"task","pageType":"interactive","templateId":"short-answer","kind":"practice","title":"2-практика: салықпен құн","prompt":"Кестені және E1 ұяшығындағы салық мөлшерін (7,5%) енгіз. Әр жолдың салығын =B3*C3*$E$1 формуласымен тап ($E$1 абсолютті), құнын салықпен есепте, E8-ге жалпы соманы жаз.","points":9,"picture":"lec/inf8-t31b-kk.svg","pictureAlt":"Салық мөлшері E1 ұяшығында, бес тағамның бағасы мен саны, салық пен жалпы құнға арналған бос ұяшықтар","sheet":{"rows":14,"cols":8},"criteria":[{"id":"c1","text":"E1 ұяшығына салық мөлшері енгізілген (7,5%)","cell":"E1","points":1,"accept":["0.07","0.075"]},{"id":"c2","text":"D3 — салық ($E$1 абсолютті сілтемемен)","cell":"D3","points":2,"formula":true,"accept":["2025"]},{"id":"c3","text":"D7 — көшірілген формула, салық дұрыс","cell":"D7","points":1,"formula":true,"accept":["1800"]},{"id":"c4","text":"E3 — кебабтың салықпен құны","cell":"E3","points":1,"formula":true,"accept":["29025"]},{"id":"c5","text":"E4 — тауық кебабының салықпен құны","cell":"E4","points":1,"formula":true,"accept":["17737.5"]},{"id":"c6","text":"E6 — лимонадтың салықпен құны","cell":"E6","points":1,"formula":true,"accept":["8600"]},{"id":"c7","text":"E8 — жалпы сома (SUM)","cell":"E8","points":2,"fn":"SUM","accept":["106962.5"]}],"steps":["Кестені көшір, E1 ұяшығына салық мөлшерін 7,5% (немесе 0,075) жаз.","D3 ұяшығына =B3*C3*$E$1 жаз: $E$1 — абсолютті сілтеме.","Формуланы D4:D7 ұяшықтарына көшір. Абсолютті сілтеме әр ұяшықта бірдей, қалғандары жолға қарай өзгеруі керек.","E3 ұяшығына құн + салық формуласын жаз (=B3*C3+D3), көшір, E8-ге SUM жаз."],"ru":{"title":"Практика 2: стоимость с налогом","prompt":"Введи таблицу и ставку налога (7,5%) в E1. Налог каждой строки найди формулой =B3*C3*$E$1 (ячейка $E$1 абсолютная), посчитай стоимость с налогом, в E8 найди итог.","picture":"lec/inf8-t31b-ru.svg","pictureAlt":"Ставка налога в E1, цена и количество пяти позиций, пустые ячейки для налога и стоимости","criteria":[{"id":"c1","text":"В E1 введена ставка налога (7,5%)","cell":"E1","points":1},{"id":"c2","text":"D3 — налог (с абсолютной ссылкой $E$1)","cell":"D3","points":2,"formula":true},{"id":"c3","text":"D7 — скопированная формула, налог верный","cell":"D7","points":1,"formula":true},{"id":"c4","text":"E3 — стоимость кебаба с налогом","cell":"E3","points":1,"formula":true},{"id":"c5","text":"E4 — стоимость куриного кебаба с налогом","cell":"E4","points":1,"formula":true},{"id":"c6","text":"E6 — стоимость лимонада с налогом","cell":"E6","points":1,"formula":true},{"id":"c7","text":"E8 — общая сумма (SUM)","cell":"E8","points":2,"fn":"SUM"}],"steps":["Перенеси таблицу, в E1 запиши ставку налога 7,5% (или 0,075).","В D3 запиши =B3*C3*$E$1: $E$1 — абсолютная ссылка.","Скопируй формулу в D4:D7. Абсолютная ссылка в каждой ячейке одинакова, остальные меняются по строке.","В E3 запиши стоимость + налог (=B3*C3+D3), скопируй, в E8 запиши SUM."]},"en":{"title":"Practice 2: cost with sales tax","prompt":"Enter the table and the tax rate (7.5%) in E1. Find each row’s tax with =B3*C3*$E$1 ($E$1 is absolute), work out the cost with tax, and find the total in E8.","picture":"lec/inf8-t31b-en.svg","pictureAlt":"Tax rate in E1, price and quantity of five items, empty cells for the tax and the cost","criteria":[{"id":"c1","text":"The tax rate is entered in E1 (7.5%)","cell":"E1","points":1},{"id":"c2","text":"D3 — the tax (with the absolute reference $E$1)","cell":"D3","points":2,"formula":true},{"id":"c3","text":"D7 — the copied formula, the tax is right","cell":"D7","points":1,"formula":true},{"id":"c4","text":"E3 — cost of the beef kebab with tax","cell":"E3","points":1,"formula":true},{"id":"c5","text":"E4 — cost of the chicken kebab with tax","cell":"E4","points":1,"formula":true},{"id":"c6","text":"E6 — cost of the lemonade with tax","cell":"E6","points":1,"formula":true},{"id":"c7","text":"E8 — the total (SUM)","cell":"E8","points":2,"fn":"SUM"}],"steps":["Copy the table and type the tax rate 7.5% (or 0.075) in E1.","In D3 type =B3*C3*$E$1: $E$1 is an absolute reference.","Copy the formula to D4:D7. The absolute reference must be the same in every cell, the others change with the row.","In E3 type cost + tax (=B3*C3+D3), copy it, and type SUM in E8."]}},{"type":"task","pageType":"interactive","templateId":"short-answer","kind":"practice","title":"3-практика: жеңілдік","prompt":"Кестені және E1 ұяшығындағы жеңілдікті (15%) енгіз. D3 ұяшығына әр тауар бойынша қанша үнемдейтінін есептейтін формула жаз (баға, саны және E1), сосын төленетін соманы тап.","points":9,"picture":"lec/inf8-t31c-kk.svg","pictureAlt":"Жеңілдік E1 ұяшығында, алты тауардың бағасы мен саны, үнемдеу мен төлемге арналған бос ұяшықтар","sheet":{"rows":14,"cols":8},"criteria":[{"id":"c1","text":"E1 ұяшығына жеңілдік енгізілген (15%)","cell":"E1","points":1,"accept":["0.15"]},{"id":"c2","text":"D3 — әр тауардан үнемдеу ($E$1 абсолютті)","cell":"D3","points":2,"formula":true,"accept":["3609"]},{"id":"c3","text":"D8 — көшірілген формула дұрыс","cell":"D8","points":1,"formula":true,"accept":["834.3"]},{"id":"c4","text":"E3 — табақтарға жеңілдікпен төлем","cell":"E3","points":1,"formula":true,"accept":["20451"]},{"id":"c5","text":"E6 — қасықтарға жеңілдікпен төлем","cell":"E6","points":1,"formula":true,"accept":["5589.6"]},{"id":"c6","text":"E8 — пышақтарға жеңілдікпен төлем","cell":"E8","points":1,"formula":true,"accept":["4727.7"]},{"id":"c7","text":"E9 — жалпы төлем (SUM)","cell":"E9","points":2,"fn":"SUM","accept":["49793.85"]}],"steps":["Кестені және E1 ұяшығына жеңілдікті (15%) енгіз.","D3: =B3*C3*$E$1 — әр тауар бойынша үнемдейтін сома. Көшіргенде $E$1 өзгермейді.","Формуланы D4:D8 ұяшықтарына көшір.","E3: =B3*C3-D3 — жеңілдікпен төленетін сома. E3:E8 көшіріп, E9-ға SUM жаз."],"ru":{"title":"Практика 3: скидка","prompt":"Введи таблицу и скидку (15%) в E1. В D3 запиши формулу, которая считает, сколько покупатель экономит на каждом товаре (цена, количество и E1), затем найди сумму к оплате.","picture":"lec/inf8-t31c-ru.svg","pictureAlt":"Скидка в E1, цена и количество шести товаров, пустые ячейки для экономии и оплаты","criteria":[{"id":"c1","text":"В E1 введена скидка (15%)","cell":"E1","points":1},{"id":"c2","text":"D3 — экономия на товаре ($E$1 абсолютная)","cell":"D3","points":2,"formula":true},{"id":"c3","text":"D8 — скопированная формула верна","cell":"D8","points":1,"formula":true},{"id":"c4","text":"E3 — оплата за тарелки со скидкой","cell":"E3","points":1,"formula":true},{"id":"c5","text":"E6 — оплата за ложки со скидкой","cell":"E6","points":1,"formula":true},{"id":"c6","text":"E8 — оплата за ножи со скидкой","cell":"E8","points":1,"formula":true},{"id":"c7","text":"E9 — общая сумма к оплате (SUM)","cell":"E9","points":2,"fn":"SUM"}],"steps":["Введи таблицу и скидку (15%) в E1.","D3: =B3*C3*$E$1 — сколько экономим на товаре. При копировании $E$1 не меняется.","Скопируй формулу в D4:D8.","E3: =B3*C3-D3 — сумма к оплате со скидкой. Скопируй в E3:E8 и запиши SUM в E9."]},"en":{"title":"Practice 3: discount","prompt":"Enter the table and the discount (15%) in E1. In D3 write a formula that works out how much the customer saves on each item (price, quantity and E1), then find the amount to pay.","picture":"lec/inf8-t31c-en.svg","pictureAlt":"Discount in E1, price and quantity of six items, empty cells for the saving and the payment","criteria":[{"id":"c1","text":"The discount is entered in E1 (15%)","cell":"E1","points":1},{"id":"c2","text":"D3 — the saving on the item ($E$1 is absolute)","cell":"D3","points":2,"formula":true},{"id":"c3","text":"D8 — the copied formula is right","cell":"D8","points":1,"formula":true},{"id":"c4","text":"E3 — payment for the plates with the discount","cell":"E3","points":1,"formula":true},{"id":"c5","text":"E6 — payment for the spoons with the discount","cell":"E6","points":1,"formula":true},{"id":"c6","text":"E8 — payment for the knives with the discount","cell":"E8","points":1,"formula":true},{"id":"c7","text":"E9 — the total to pay (SUM)","cell":"E9","points":2,"fn":"SUM"}],"steps":["Enter the table and the discount (15%) in E1.","D3: =B3*C3*$E$1 — what is saved on the item. $E$1 does not change when copied.","Copy the formula to D4:D8.","E3: =B3*C3-D3 — the amount to pay after the discount. Copy it to E3:E8 and type SUM in E9."]}},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"Сауаттылық: қайталау сұрақтары","bullets":["Салыстырмалы және абсолютті сілтеменің айырмашылығы неде?","Қай түрін жиі қолданамыз? Неге?","Ұяшыққа абсолютті сілтемені қалай қолданамыз?","Абсолютті сілтемені тек жол немесе тек баған бойынша қалай орнатамыз?"],"notes":"Жауаптары: 1) салыстырмалы көшіргенде өзгереді, абсолютті өзгермейді; 2) салыстырмалы әдепкі, бірақ тұрақты шамаға (салық, жеңілдік) $A$2 қолданылады; 3) баған мен жол алдына $ қою; 4) A$2 — жол бекітіледі, $A2 — баған бекітіледі.","ru":{"title":"Грамотность: вопросы для повторения","bullets":["Чем отличаются относительные и абсолютные ссылки?","Какой вид ссылок используют чаще? Почему?","Как сделать ссылку на ячейку абсолютной?","Как закрепить ссылку только по строке или только по столбцу?"],"notes":"Ответы: 1) относительные меняются при копировании, абсолютные нет; 2) относительные по умолчанию, а для постоянной величины (налог, скидка) нужна $A$2; 3) поставить $ перед столбцом и строкой; 4) A$2 — закреплена строка, $A2 — столбец."},"en":{"title":"Literacy: review questions","bullets":["What is the difference between relative and absolute references?","Which type of cell reference do we use often? Why?","How do you apply an absolute reference to a cell?","Explain the setting of an absolute cell reference based on the row or column only."],"notes":"Answers: 1) relative references change when copied, absolute ones do not; 2) relative is the default, but a constant (tax, discount) needs $A$2; 3) put $ before the column and the row; 4) A$2 pins the row, $A2 pins the column."},"design":"lab"}]$sl$::jsonb),
    ($sl$3.2 Кірістірілген функциялар$sl$, $sl$Информатика$sl$, 1, $sl${"summary":"Функция — аты бар дайын формула. SUM, AVERAGE, MIN, MAX, COUNT, ROUND функциялары, олардың жазылуы және диапазонды көрсету.","objectives":["Функцияның жазылуын түсіну: аты және аргументтері","SUM, AVERAGE, MIN, MAX, COUNT функцияларын қолдану","Диапазонды дұрыс көрсету"],"grade":8,"duration":"45 минут","ru":{"summary":"Функция — готовая формула с именем. Функции SUM, AVERAGE, MIN, MAX, COUNT, ROUND, их запись и указание диапазона.","objectives":["Понимать запись функции: имя и аргументы","Применять функции SUM, AVERAGE, MIN, MAX, COUNT","Правильно задавать диапазон"]},"en":{"summary":"A function is a ready-made formula with a name: SUM, AVERAGE, MIN, MAX, COUNT, ROUND, how to write them and how to give a range.","objectives":["Understand how a function is written: name and arguments","Use SUM, AVERAGE, MIN, MAX, COUNT","Give a range correctly"]}}$sl$::jsonb, $sl$[{"term":"function","definition":"Функция — аты бар дайын формула, мысалы SUM · Функция — готовая формула с именем, например SUM · Function — a ready-made formula with a name, e.g. SUM"},{"term":"argument","definition":"Аргумент — функция жақшада алатын мән немесе диапазон · Аргумент — значение или диапазон в скобках функции · Argument — the value or range a function takes in brackets"},{"term":"range","definition":"Диапазон — ұяшықтар тобы, мысалы B2:B6 · Диапазон — группа ячеек, например B2:B6 · Range — a group of cells, e.g. B2:B6"}]$sl$::jsonb, $sl$[{"type":"title","pageType":"slide","templateId":"title","title":"3.2 Кірістірілген функциялар","subtitle":"Информатика 8-сынып · 3-тарау «Электрондық кестелер»","ru":{"title":"3.2 Встроенные функции","subtitle":"Информатика 8 класс · глава 3 «Электронные таблицы»"},"en":{"title":"3.2 Built-in functions","subtitle":"Informatics Grade 8 · Chapter 3 “Spreadsheets”"},"design":"lab"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"Функция деген не?","bullets":["Функция — аты бар дайын формула. Ұзын қосуды қолмен жазбай, бір сөзбен орындаймыз.","Жазылуы: =АТЫ(аргументтер). Аргумент — жақша ішіндегі ұяшықтар немесе сандар.","Аргументтерді «;» немесе «,» бөліп жазамыз, диапазонды «:» таңбасымен: B2:B6."],"art":"functions","ru":{"title":"Что такое функция?","bullets":["Функция — готовая формула с именем. Не пишем длинное сложение вручную, а вызываем одним словом.","Запись: =ИМЯ(аргументы). Аргумент — ячейки или числа в скобках.","Аргументы разделяют «;» или «,», а диапазон записывают через «:» — B2:B6."]},"en":{"title":"What is a function?","bullets":["A function is a ready-made formula with a name. Instead of a long sum by hand, we call it by one word.","Form: =NAME(arguments). An argument is the cells or numbers inside the brackets.","Arguments are separated by “;” or “,”, a range uses “:” — B2:B6."]},"design":"lab"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"Негізгі функциялар","bullets":["SUM — қосынды, AVERAGE — орташа мән, COUNT — сандардың саны.","MAX — ең үлкен мән, MIN — ең кіші мән, ROUND — дөңгелектеу.","Функция ішіне функция жазуға болады: =ROUND(AVERAGE(B2:B6);1)."],"code":"=SUM(B2:B6)\n=AVERAGE(B2:B6)\n=MAX(B2:B6)\n=MIN(B2:B6)\n=COUNT(B2:B6)\n=ROUND(B7;1)","lang":"text","ru":{"title":"Основные функции","bullets":["SUM — сумма, AVERAGE — среднее, COUNT — количество чисел.","MAX — наибольшее значение, MIN — наименьшее, ROUND — округление.","Одну функцию можно вложить в другую: =ROUND(AVERAGE(B2:B6);1)."]},"en":{"title":"The main functions","bullets":["SUM adds up, AVERAGE gives the mean, COUNT counts the numbers.","MAX is the largest value, MIN the smallest, ROUND rounds a number.","A function can sit inside another one: =ROUND(AVERAGE(B2:B6);1)."]},"design":"lab"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"Функцияны қалай енгіземіз?","bullets":["Нәтиже шығатын ұяшықты бас, «=» таңбасын және функция атын жаз.","Жақшаны ашып, диапазонды тінтуірмен сүйреп белгіле немесе қолмен жаз, жақшаны жап.","Enter бас. Мәндер өзгерсе, нәтиже өздігінен қайта есептеледі."],"art":"recalc","ru":{"title":"Как ввести функцию?","bullets":["Нажми на ячейку для результата, напиши «=» и имя функции.","Открой скобку, выдели диапазон мышью или напиши вручную, закрой скобку.","Нажми Enter. Если значения изменятся, результат пересчитается сам."]},"en":{"title":"How do we enter a function?","bullets":["Click the cell for the result, type “=” and the function name.","Open the bracket, drag over the range or type it, close the bracket.","Press Enter. If the values change, the result recalculates by itself."]},"design":"lab"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"video","title":"Видео: кестедегі функциялар","bullets":["Видеоны көр, сосын екі сұраққа жауап бер: функция қалай басталады? Диапазон қалай жазылады?"],"notes":"Видео ашылмаса, астындағы «YouTube-та ашу» сілтемесін басыңыз. Басқа видео қосу үшін дәріс өңдегішінде «YouTube видео» өрісіне сілтемесін қойыңыз.","video":"RBVub9rdF40","ru":{"title":"Видео: функции в таблице","bullets":["Посмотри видео и ответь на два вопроса: как начинается функция? Как записывается диапазон?"],"notes":"Если видео не открывается, нажмите ссылку «Смотреть на YouTube» под ним. Другое видео можно вставить в поле «YouTube видео» в редакторе урока."},"en":{"title":"Video: spreadsheet functions","bullets":["Watch the video and answer two questions: how does a function start? How is a range written?"],"notes":"If the video does not play, use the “Open on YouTube” link under it. To use another video, paste its link into the “YouTube video” field in the lesson editor."},"design":"lab"},{"type":"solution","pageType":"slide","templateId":"worked-example","kind":"exampletask","title":"Мысал: сатылым кестесі","sections":[{"h":"Шарты","text":"B2:B6 ұяшықтарында бес күндегі сатылым: 120, 80, 100, 60, 40. Қосындысын, орташасын, ең үлкенін, ең кішісін және күн санын тап."},{"h":"Алгоритм (қадамдар)","bullets":["B7-ге =SUM(B2:B6) жаз.","B8-ге =AVERAGE(B2:B6) жаз.","B9-ға =MAX(B2:B6), B10-ға =MIN(B2:B6) жаз.","B11-ге =COUNT(B2:B6) жаз."]},{"h":"Шешімі","text":"Қосынды 400, орташа 80, ең үлкен 120, ең кіші 40, күн саны 5.","hide":true}],"ru":{"title":"Пример: таблица продаж","sections":[{"h":"Условие","text":"В ячейках B2:B6 продажи за пять дней: 120, 80, 100, 60, 40. Найди сумму, среднее, наибольшее, наименьшее и количество дней."},{"h":"Алгоритм (шаги)","bullets":["В B7 запиши =SUM(B2:B6).","В B8 запиши =AVERAGE(B2:B6).","В B9 запиши =MAX(B2:B6), в B10 — =MIN(B2:B6).","В B11 запиши =COUNT(B2:B6)."]},{"h":"Решение","text":"Сумма 400, среднее 80, наибольшее 120, наименьшее 40, дней 5.","hide":true}]},"en":{"title":"Example: a sales table","sections":[{"h":"Task","text":"Cells B2:B6 hold five days of sales: 120, 80, 100, 60, 40. Find the sum, mean, largest, smallest and the number of days."},{"h":"Steps","bullets":["In B7 type =SUM(B2:B6).","In B8 type =AVERAGE(B2:B6).","In B9 type =MAX(B2:B6), in B10 =MIN(B2:B6).","In B11 type =COUNT(B2:B6)."]},{"h":"Solution","text":"Sum 400, mean 80, largest 120, smallest 40, 5 days.","hide":true}]},"design":"lab"},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"SUM функциясы","prompt":"A1:A4 ұяшықтарында 2, 4, 6, 8 сандары бар. =SUM(A1:A4) нәтижесі қандай?","options":["14","20","5","8"],"answer":1,"explanation":"2 + 4 + 6 + 8 = 20.","points":1,"ru":{"title":"Функция SUM","prompt":"В ячейках A1:A4 числа 2, 4, 6, 8. Каков результат =SUM(A1:A4)?","options":["14","20","5","8"],"explanation":"2 + 4 + 6 + 8 = 20."},"en":{"title":"The SUM function","prompt":"Cells A1:A4 hold 2, 4, 6, 8. What does =SUM(A1:A4) give?","options":["14","20","5","8"],"explanation":"2 + 4 + 6 + 8 = 20."}},{"type":"task","pageType":"interactive","templateId":"short-answer","kind":"practice","title":"Практика: асхана сатылымы","prompt":"Суреттегі кестені енгіз және қосындыларды, ең үлкен мәнді, орташа мәнді функциялармен есепте.","points":12,"picture":"lec/inf8-t32-kk.svg","pictureAlt":"Үш күндегі бес тағамның сатылым кестесі, бос ұяшықтар қосындылар мен ең көбі, орташа үшін","sheet":{"rows":14,"cols":8},"criteria":[{"id":"c1","text":"Деректер енгізілген: B2 = 12 және D6 = 5","cell":"D6","points":1,"accept":["5"]},{"id":"c2","text":"E2 — бөлкенің үш күндегі қосындысы (SUM)","cell":"E2","points":2,"fn":"SUM","accept":["37"]},{"id":"c3","text":"E6 — салаттың қосындысы","cell":"E6","points":1,"fn":"SUM","accept":["21"]},{"id":"c4","text":"B7 — дүйсенбінің қосындысы","cell":"B7","points":2,"fn":"SUM","accept":["61"]},{"id":"c5","text":"E7 — жалпы қосынды","cell":"E7","points":2,"fn":"SUM","accept":["177"]},{"id":"c6","text":"B8 — барлық кестедегі ең үлкен мән (MAX)","cell":"B8","points":2,"fn":"MAX","accept":["22"]},{"id":"c7","text":"B9 — барлық сандардың орташасы (AVERAGE)","cell":"B9","points":2,"fn":"AVERAGE","accept":["11.8"]}],"ru":{"title":"Практика: продажи в столовой","prompt":"Введи таблицу с рисунка и посчитай суммы, наибольшее и среднее значения функциями.","picture":"lec/inf8-t32-ru.svg","pictureAlt":"Таблица продаж пяти блюд за три дня, пустые ячейки для сумм, максимума и среднего","criteria":[{"id":"c1","text":"Данные введены: B2 = 12 и D6 = 5","cell":"D6","points":1},{"id":"c2","text":"E2 — сумма по булочкам за три дня (SUM)","cell":"E2","points":2,"fn":"SUM"},{"id":"c3","text":"E6 — сумма по салату","cell":"E6","points":1,"fn":"SUM"},{"id":"c4","text":"B7 — сумма за понедельник","cell":"B7","points":2,"fn":"SUM"},{"id":"c5","text":"E7 — общая сумма","cell":"E7","points":2,"fn":"SUM"},{"id":"c6","text":"B8 — наибольшее значение во всей таблице (MAX)","cell":"B8","points":2,"fn":"MAX"},{"id":"c7","text":"B9 — среднее всех чисел (AVERAGE)","cell":"B9","points":2,"fn":"AVERAGE"}]},"en":{"title":"Practice: canteen sales","prompt":"Enter the table from the picture and work out the totals, the largest and the mean with functions.","picture":"lec/inf8-t32-en.svg","pictureAlt":"Sales of five items over three days with empty cells for totals, largest and mean","criteria":[{"id":"c1","text":"Data entered: B2 = 12 and D6 = 5","cell":"D6","points":1},{"id":"c2","text":"E2 — buns over three days (SUM)","cell":"E2","points":2,"fn":"SUM"},{"id":"c3","text":"E6 — salads total","cell":"E6","points":1,"fn":"SUM"},{"id":"c4","text":"B7 — Monday total","cell":"B7","points":2,"fn":"SUM"},{"id":"c5","text":"E7 — grand total","cell":"E7","points":2,"fn":"SUM"},{"id":"c6","text":"B8 — largest value in the whole table (MAX)","cell":"B8","points":2,"fn":"MAX"},{"id":"c7","text":"B9 — mean of all the numbers (AVERAGE)","cell":"B9","points":2,"fn":"AVERAGE"}]}},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"COUNT","prompt":"COUNT функциясы нені санайды?","options":["Ұяшықтардың барлығын","Тек сандар бар ұяшықтарды","Мәтіндерді ғана","Диапазон қосындысын"],"answer":1,"explanation":"COUNT тек сандарды санайды, мәтін мен бос ұяшықты өткізіп жібереді.","points":1,"ru":{"title":"COUNT","prompt":"Что считает функция COUNT?","options":["Все ячейки подряд","Только ячейки с числами","Только тексты","Сумму диапазона"],"explanation":"COUNT считает только числа, текст и пустые ячейки пропускает."},"en":{"title":"COUNT","prompt":"What does the COUNT function count?","options":["All cells","Only the cells that hold numbers","Only texts","The sum of the range"],"explanation":"COUNT counts only numbers and skips text and empty cells."}}]$sl$::jsonb),
    ($sl$3.3 Есеп шығару: функциялар мен формулалар$sl$, $sl$Информатика$sl$, 2, $sl${"summary":"Есепті кестеде шешу жолы: деректер, формула, көшіру. Абсолютті сілтеме ($), IF функциясы және салыстыру амалдары.","objectives":["Есепті кестеде шешу алгоритмін қолдану","Формуланы көшіргенде сілтеменің қалай өзгеретінін түсіну","IF функциясымен шарт жазу"],"grade":8,"duration":"45 минут","ru":{"summary":"Как решать задачу в таблице: данные, формула, копирование. Абсолютная ссылка ($), функция IF и операции сравнения.","objectives":["Применять алгоритм решения задачи в таблице","Понимать, как меняются ссылки при копировании формулы","Записывать условие функцией IF"]},"en":{"summary":"How to solve a problem in a sheet: data, formula, copying. Absolute references ($), the IF function and comparisons.","objectives":["Follow the steps for solving a problem in a sheet","Understand how references change when a formula is copied","Write a condition with IF"]}}$sl$::jsonb, $sl$[{"term":"relative reference","definition":"Салыстырмалы сілтеме (A1) — формуланы көшіргенде өзгереді · Относительная ссылка (A1) меняется при копировании формулы · Relative reference (A1) — changes when the formula is copied"},{"term":"absolute reference","definition":"Абсолютті сілтеме ($A$1) — көшіргенде өзгермейді · Абсолютная ссылка ($A$1) не меняется при копировании · Absolute reference ($A$1) — stays the same when copied"},{"term":"IF","definition":"IF(шарт; егер рас; егер жалған) — шартқа қарай екі мәннің бірін таңдайды · IF(условие; если истина; если ложь) — выбирает одно из двух значений · IF(condition; if true; if false) — picks one of two values"}]$sl$::jsonb, $sl$[{"type":"title","pageType":"slide","templateId":"title","title":"3.3 Есеп шығару: функциялар мен формулалар","subtitle":"Информатика 8-сынып · 3-тарау «Электрондық кестелер»","ru":{"title":"3.3 Решение задач: функции и формулы","subtitle":"Информатика 8 класс · глава 3 «Электронные таблицы»"},"en":{"title":"3.3 Problem solving: functions and formulas","subtitle":"Informatics Grade 8 · Chapter 3 “Spreadsheets”"},"design":"lab"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"Есепті кестеде шешу қадамдары","bullets":["Шартты оқы: не берілген, нені табу керек?","Берілген деректерді кестеге жаз, нәтиже үшін орын қалдыр.","Бірінші жолға формула жаз, оны төмен қарай көшір.","Жауапты тексер: бір-екі есепті қолмен есептеп салыстыр."],"art":"steps","ru":{"title":"Шаги решения задачи в таблице","bullets":["Прочитай условие: что дано и что найти?","Запиши данные в таблицу, оставь место для результата.","Запиши формулу в первой строке и протяни её вниз.","Проверь ответ: пересчитай одну-две строки вручную."]},"en":{"title":"Steps for solving a problem in a sheet","bullets":["Read the problem: what is given and what must be found?","Put the given data in the table and leave room for the result.","Write the formula in the first row and fill it down.","Check the answer: recalculate one or two rows by hand."]},"design":"lab"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"Формулалар мен сілтемелер","bullets":["Құны = баға × саны: =B2*C2. Формуланы төмен көшіргенде жол нөмірі өздігінен өзгереді.","Тұрақты ұяшыққа ($) қояды: =B2*$B$8. Доллар белгісі сілтемені «бекітеді».","Пайыз: =B2/$B$9*100 — үлесті бүтінге бөліп, 100-ге көбейтеміз."],"code":"=B2*C2      cost\n=D2*$B$8    fixed cell\n=B2/$B$9*100  percent","lang":"text","art":"refs","ru":{"title":"Формулы и ссылки","bullets":["Стоимость = цена × количество: =B2*C2. При копировании вниз номер строки меняется сам.","На постоянную ячейку ставят $: =B2*$B$8. Знак доллара «закрепляет» ссылку.","Процент: =B2/$B$9*100 — делим часть на целое и умножаем на 100."]},"en":{"title":"Formulas and references","bullets":["Cost = price × quantity: =B2*C2. When copied down, the row number changes by itself.","Pin a constant cell with $: =B2*$B$8. The dollar sign “locks” the reference.","Percentage: =B2/$B$9*100 — divide the part by the whole and multiply by 100."]},"design":"lab"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"Шарт және IF функциясы","bullets":["IF(шарт; егер рас; егер жалған) шарт орындалса бірінші мәнді, болмаса екіншісін береді.","Салыстыру белгілері: > үлкен, < кіші, >= үлкен немесе тең, <= кіші немесе тең, = тең, <> тең емес."],"code":"=IF(B2>=50;1;0)\n=IF(D6>1000;D6*0.9;D6)","lang":"text","art":"ifflow","ru":{"title":"Условие и функция IF","bullets":["IF(условие; если истина; если ложь) даёт первое значение, если условие выполнено, иначе второе.","Знаки сравнения: > больше, < меньше, >= больше или равно, <= меньше или равно, = равно, <> не равно."]},"en":{"title":"Conditions and the IF function","bullets":["IF(condition; if true; if false) gives the first value when the condition holds, otherwise the second.","Comparison signs: > greater, < less, >= greater or equal, <= less or equal, = equal, <> not equal."]},"design":"lab"},{"type":"solution","pageType":"slide","templateId":"worked-example","kind":"exampletask","title":"Мысал: чек және жеңілдік","sections":[{"h":"Шарты","text":"Дәптер 150 × 4, қалам 80 × 3, сызғыш 120 × 2. Барлығы 1000-нан көп болса, 10% жеңілдік беріледі. Төлем сомасын тап."},{"h":"Алгоритм (қадамдар)","bullets":["D2 = B2*C2 жаз да, D4-ке дейін төмен көшір.","D5 = SUM(D2:D4) — жалпы сома.","D6 = IF(D5>1000;D5*0.9;D5) — жеңілдікпен."]},{"h":"Шешімі","text":"600 + 240 + 240 = 1080 > 1000, сондықтан төлем 1080 × 0,9 = 972.","hide":true}],"ru":{"title":"Пример: чек и скидка","sections":[{"h":"Условие","text":"Тетрадь 150 × 4, ручка 80 × 3, линейка 120 × 2. Если всего больше 1000, скидка 10%. Найди сумму к оплате."},{"h":"Алгоритм (шаги)","bullets":["В D2 запиши =B2*C2 и протяни до D4.","D5 = SUM(D2:D4) — общая сумма.","D6 = IF(D5>1000;D5*0.9;D5) — со скидкой."]},{"h":"Решение","text":"600 + 240 + 240 = 1080 > 1000, поэтому к оплате 1080 × 0,9 = 972.","hide":true}]},"en":{"title":"Example: a receipt and a discount","sections":[{"h":"Task","text":"A notebook 150 × 4, a pen 80 × 3, a ruler 120 × 2. If the total is above 1000, there is a 10% discount. Find the amount to pay."},{"h":"Steps","bullets":["In D2 type =B2*C2 and fill down to D4.","D5 = SUM(D2:D4) — the total.","D6 = IF(D5>1000;D5*0.9;D5) — with the discount."]},{"h":"Solution","text":"600 + 240 + 240 = 1080 > 1000, so you pay 1080 × 0.9 = 972.","hide":true}]},"design":"lab"},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"IF функциясы","prompt":"A1 ұяшығында 7 бар. =IF(A1>10;\"көп\";\"аз\") нені береді?","options":["көп","аз","7","қате"],"answer":1,"explanation":"7 > 10 — жалған, сондықтан үшінші аргумент шығады.","points":1,"ru":{"title":"Функция IF","prompt":"В A1 число 7. Что даст =IF(A1>10;\"много\";\"мало\")?","options":["много","мало","7","ошибка"],"explanation":"7 > 10 — ложь, поэтому берётся третий аргумент."},"en":{"title":"The IF function","prompt":"A1 holds 7. What does =IF(A1>10;\"many\";\"few\") return?","options":["many","few","7","an error"],"explanation":"7 > 10 is false, so the third argument is returned."}},{"type":"task","pageType":"interactive","templateId":"short-answer","kind":"practice","title":"Практика: чек және жеңілдік","prompt":"Суреттегі чекті енгіз. Әр тауардың құнын, жалпы соманы, жеңілдікті және төленетін соманы формуламен есепте.","points":10,"picture":"lec/inf8-t33-kk.svg","pictureAlt":"Төрт тауардың бағасы мен саны, жеңілдік 10%, құн, жалпы сома және төлем үшін бос ұяшықтар","sheet":{"rows":14,"cols":8},"criteria":[{"id":"c1","text":"Деректер енгізілген: B2 = 150 және C5 = 3","cell":"C5","points":1,"accept":["3"]},{"id":"c2","text":"D2 — дәптердің құны (формуламен)","cell":"D2","points":1,"formula":true,"accept":["600"]},{"id":"c3","text":"D5 — папкалардың құны (формуламен)","cell":"D5","points":1,"formula":true,"accept":["270"]},{"id":"c4","text":"D6 — жалпы сома (SUM)","cell":"D6","points":2,"fn":"SUM","accept":["1510"]},{"id":"c5","text":"D9 — жеңілдік сомасы (формуламен)","cell":"D9","points":2,"formula":true,"accept":["151"]},{"id":"c6","text":"D10 — төленетін сома (IF функциясымен)","cell":"D10","points":3,"fn":"IF","accept":["1359"]}],"ru":{"title":"Практика: чек и скидка","prompt":"Введи чек с рисунка. Формулами посчитай стоимость каждого товара, общую сумму, скидку и сумму к оплате.","picture":"lec/inf8-t33-ru.svg","pictureAlt":"Цена и количество четырёх товаров, скидка 10%, пустые ячейки для стоимости, суммы и оплаты","criteria":[{"id":"c1","text":"Данные введены: B2 = 150 и C5 = 3","cell":"C5","points":1},{"id":"c2","text":"D2 — стоимость тетрадей (формулой)","cell":"D2","points":1,"formula":true},{"id":"c3","text":"D5 — стоимость папок (формулой)","cell":"D5","points":1,"formula":true},{"id":"c4","text":"D6 — общая сумма (SUM)","cell":"D6","points":2,"fn":"SUM"},{"id":"c5","text":"D9 — сумма скидки (формулой)","cell":"D9","points":2,"formula":true},{"id":"c6","text":"D10 — сумма к оплате (функцией IF)","cell":"D10","points":3,"fn":"IF"}]},"en":{"title":"Practice: a receipt and a discount","prompt":"Enter the receipt from the picture. With formulas work out each item’s cost, the total, the discount and the amount to pay.","picture":"lec/inf8-t33-en.svg","pictureAlt":"Price and quantity of four items, a 10% discount, empty cells for cost, total and amount to pay","criteria":[{"id":"c1","text":"Data entered: B2 = 150 and C5 = 3","cell":"C5","points":1},{"id":"c2","text":"D2 — cost of the notebooks (formula)","cell":"D2","points":1,"formula":true},{"id":"c3","text":"D5 — cost of the folders (formula)","cell":"D5","points":1,"formula":true},{"id":"c4","text":"D6 — the total (SUM)","cell":"D6","points":2,"fn":"SUM"},{"id":"c5","text":"D9 — discount amount (formula)","cell":"D9","points":2,"formula":true},{"id":"c6","text":"D10 — amount to pay (with IF)","cell":"D10","points":3,"fn":"IF"}]}},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Абсолютті сілтеме","prompt":"Формуланы көшіргенде $B$1 сілтемесі қалай өзгереді?","options":["Жол нөмірі өзгереді","Баған әрпі өзгереді","Өзгермейді","Жойылады"],"answer":2,"explanation":"$ белгісі баған мен жолды бекітеді, ссылка әрқашан B1-ді көрсетеді.","points":1,"ru":{"title":"Абсолютная ссылка","prompt":"Как изменится ссылка $B$1 при копировании формулы?","options":["Изменится номер строки","Изменится буква столбца","Не изменится","Исчезнет"],"explanation":"Знак $ закрепляет столбец и строку, ссылка всегда указывает на B1."},"en":{"title":"Absolute reference","prompt":"What happens to the reference $B$1 when a formula is copied?","options":["The row number changes","The column letter changes","It stays the same","It disappears"],"explanation":"The $ signs lock the column and the row, so it always points at B1."}}]$sl$::jsonb),
    ($sl$3.4 Қолда бар ақпарат бойынша деректерді талдау$sl$, $sl$Информатика$sl$, 3, $sl${"summary":"Деректерді талдау жолы: сұрақ, деректер, есептеу, диаграмма, қорытынды. COUNTIF, SUMIF, AVERAGEIF, LARGE, SMALL және диаграмма түрін таңдау.","objectives":["Сұрақ қойып, жауапты кестеден табу","COUNTIF, SUMIF, AVERAGEIF функцияларын қолдану","Диаграмма түрін дұрыс таңдау"],"grade":8,"duration":"45 минут","ru":{"summary":"Путь анализа данных: вопрос, данные, расчёт, диаграмма, вывод. COUNTIF, SUMIF, AVERAGEIF, LARGE, SMALL и выбор вида диаграммы.","objectives":["Ставить вопрос и находить ответ в таблице","Применять функции COUNTIF, SUMIF, AVERAGEIF","Правильно выбирать вид диаграммы"]},"en":{"summary":"How to analyse data: question, data, calculation, chart, conclusion. COUNTIF, SUMIF, AVERAGEIF, LARGE, SMALL and choosing a chart.","objectives":["Ask a question and find the answer in a table","Use COUNTIF, SUMIF, AVERAGEIF","Choose the right chart type"]}}$sl$::jsonb, $sl$[{"term":"COUNTIF","definition":"COUNTIF(диапазон; шарт) — шартқа сәйкес ұяшықтар санын табады · COUNTIF(диапазон; условие) — считает ячейки, подходящие под условие · COUNTIF(range; condition) — counts the cells that meet the condition"},{"term":"SUMIF","definition":"SUMIF(диапазон; шарт; қосу диапазоны) — шартқа сәйкес сандарды қосады · SUMIF(диапазон; условие; диапазон суммирования) — складывает подходящие числа · SUMIF(range; condition; sum range) — adds the numbers that meet the condition"},{"term":"chart","definition":"Диаграмма — деректерді көрнекі көрсететін сурет · Диаграмма — наглядное изображение данных · Chart — a picture that shows data at a glance"}]$sl$::jsonb, $sl$[{"type":"title","pageType":"slide","templateId":"title","title":"3.4 Қолда бар ақпарат бойынша деректерді талдау","subtitle":"Информатика 8-сынып · 3-тарау «Электрондық кестелер»","ru":{"title":"3.4 Анализ данных на основе имеющейся информации","subtitle":"Информатика 8 класс · глава 3 «Электронные таблицы»"},"en":{"title":"3.4 Data analysis based on available information","subtitle":"Informatics Grade 8 · Chapter 3 “Spreadsheets”"},"design":"lab"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"Талдау қалай жүргізіледі?","bullets":["Сұрақ қой: нені білгіміз келеді? Мысалы: қай сынып жақсы нәтиже көрсетті?","Қажетті деректерді таңда, кестеге қой, қателерін тексер.","Формулалармен есепте, диаграмма сыз, сосын сөзбен қорытынды жаз."],"art":"analysis","ru":{"title":"Как проводят анализ?","bullets":["Поставь вопрос: что мы хотим узнать? Например: какой класс показал лучший результат?","Выбери нужные данные, помести в таблицу, проверь на ошибки.","Посчитай формулами, построй диаграмму и напиши вывод словами."]},"en":{"title":"How is an analysis done?","bullets":["Ask a question: what do we want to find out? For example: which class did best?","Pick the data you need, put it in a table and check it for mistakes.","Calculate with formulas, draw a chart, then write the conclusion in words."]},"design":"lab"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"Шартты функциялар","bullets":["COUNTIF — шартқа сәйкес ұяшықтарды санайды, SUMIF — сәйкес сандарды қосады, AVERAGEIF — орташасын табады.","Шарт мәтін болса, тырнақшада жазамыз: \"8A\". Сан салыстыруда: \">20\".","LARGE(диапазон; k) — k-шы ең үлкен, SMALL(диапазон; k) — k-шы ең кіші мән."],"code":"=COUNTIF(A2:A9;\"8A\")\n=SUMIF(A2:A9;\"8A\";B2:B9)\n=AVERAGEIF(A2:A9;\"8A\";B2:B9)\n=LARGE(B2:B9;2)","lang":"text","art":"countif","ru":{"title":"Функции с условием","bullets":["COUNTIF считает ячейки по условию, SUMIF складывает подходящие числа, AVERAGEIF находит их среднее.","Условие-текст пишем в кавычках: \"8A\". Сравнение с числом: \">20\".","LARGE(диапазон; k) — k-е по величине, SMALL(диапазон; k) — k-е с конца."]},"en":{"title":"Functions with a condition","bullets":["COUNTIF counts the cells that meet a condition, SUMIF adds the matching numbers, AVERAGEIF finds their mean.","A text condition goes in quotes: \"8A\". A number comparison: \">20\".","LARGE(range; k) gives the k-th largest value, SMALL(range; k) the k-th smallest."]},"design":"lab"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"Диаграмма түрін таңдау","bullets":["Бағаналы (сызықтық) диаграмма мәндерді салыстырады: сыныптар нәтижесі.","Сызықты диаграмма уақыт бойынша өзгерісті көрсетеді: температура күндер бойынша.","Дөңгелек диаграмма бүтіннің үлесін көрсетеді: бюджеттің бөлінуі. Диаграммаға тақырып пен белгі қоюды ұмытпа."],"art":"charts","ru":{"title":"Выбор вида диаграммы","bullets":["Столбчатая диаграмма сравнивает значения: результаты классов.","Линейный график показывает изменение во времени: температура по дням.","Круговая диаграмма показывает доли целого: распределение бюджета. Не забудь про заголовок и подписи."]},"en":{"title":"Choosing a chart","bullets":["A column chart compares values: the results of classes.","A line chart shows change over time: temperature day by day.","A pie chart shows shares of a whole: how a budget is split. Do not forget a title and labels."]},"design":"lab"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"Сұрыптау және сүзу","bullets":["Толық кестелік редакторда (Excel, Google Sheets) деректер мәзірінде «Сұрыптау» мен «Сүзгі» бар.","Сұрыптау жолдарды өсу немесе кему ретімен қояды, сүзгі шартқа сәйкес жолдарды ғана қалдырады.","Біздің мини-кестеде мұны LARGE, SMALL және COUNTIF формулаларымен орындаймыз."],"ru":{"title":"Сортировка и фильтрация","bullets":["В полном редакторе (Excel, Google Sheets) в меню «Данные» есть «Сортировка» и «Фильтр».","Сортировка расставляет строки по возрастанию или убыванию, фильтр оставляет только строки по условию.","В нашей мини-таблице то же самое делаем формулами LARGE, SMALL и COUNTIF."]},"en":{"title":"Sorting and filtering","bullets":["Full spreadsheet programs (Excel, Google Sheets) have Sort and Filter in the Data menu.","Sorting puts rows in ascending or descending order; a filter keeps only the rows that meet a condition.","In our mini sheet we do the same with LARGE, SMALL and COUNTIF."]},"design":"lab"},{"type":"solution","pageType":"slide","templateId":"worked-example","kind":"exampletask","title":"Мысал: бағалар талдауы","sections":[{"h":"Шарты","text":"Сегіз оқушының бағасы B2:B9 ұяшықтарында: 5, 4, 5, 3, 4, 5, 2, 4. Қанша оқушы «5» алды? Орташа баға қандай?"},{"h":"Алгоритм (қадамдар)","bullets":["«5» санын =COUNTIF(B2:B9;5) формуласымен санаймыз.","Орташа баға: =AVERAGE(B2:B9).","Қорытындыны сөзбен жазамыз."]},{"h":"Шешімі","text":"3 оқушы «5» алды, орташа баға 4 (32 ÷ 8).","hide":true}],"ru":{"title":"Пример: анализ оценок","sections":[{"h":"Условие","text":"Оценки восьми учеников в B2:B9: 5, 4, 5, 3, 4, 5, 2, 4. Сколько учеников получили «5»? Какая средняя оценка?"},{"h":"Алгоритм (шаги)","bullets":["Пятёрки считаем формулой =COUNTIF(B2:B9;5).","Средняя оценка: =AVERAGE(B2:B9).","Вывод пишем словами."]},{"h":"Решение","text":"3 ученика получили «5», средняя оценка 4 (32 ÷ 8).","hide":true}]},"en":{"title":"Example: analysing marks","sections":[{"h":"Task","text":"Marks of eight pupils in B2:B9: 5, 4, 5, 3, 4, 5, 2, 4. How many got a 5? What is the mean mark?"},{"h":"Steps","bullets":["Count the 5s with =COUNTIF(B2:B9;5).","Mean mark: =AVERAGE(B2:B9).","Write the conclusion in words."]},{"h":"Solution","text":"3 pupils got a 5; the mean mark is 4 (32 ÷ 8).","hide":true}]},"design":"lab"},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Диаграмма түрі","prompt":"Бюджеттің қандай бөлігі тамаққа кетеді — қай диаграмма ең қолайлы?","options":["Дөңгелек","Сызықты","Нүктелі","Кесте"],"answer":0,"explanation":"Үлес пен бүтінді дөңгелек диаграмма көрсетеді.","points":1,"ru":{"title":"Вид диаграммы","prompt":"Какая диаграмма лучше всего покажет, какая часть бюджета уходит на еду?","options":["Круговая","Линейный график","Точечная","Таблица"],"explanation":"Доли целого показывает круговая диаграмма."},"en":{"title":"Chart type","prompt":"Which chart shows best what share of a budget goes on food?","options":["Pie","Line","Scatter","A table"],"explanation":"A pie chart shows the shares of a whole."}},{"type":"task","pageType":"interactive","templateId":"short-answer","kind":"practice","title":"Практика: олимпиада нәтижелері","prompt":"Суреттегі кестені енгіз. Сұрақтарға жауапты COUNTIF, SUMIF, AVERAGEIF және LARGE функцияларымен тап.","points":10,"picture":"lec/inf8-t34-kk.svg","pictureAlt":"Сегіз оқушының сыныбы мен ұпайы, төменде төрт сұрақ үшін бос ұяшықтар","sheet":{"rows":14,"cols":8},"criteria":[{"id":"c1","text":"Деректер енгізілген: A2 = 8A, B2 = 21","cell":"B2","points":1,"accept":["21"]},{"id":"c2","text":"Соңғы жол енгізілген: B9 = 26","cell":"B9","points":1,"accept":["26"]},{"id":"c3","text":"B11 — 8B оқушыларының саны (COUNTIF)","cell":"B11","points":2,"fn":"COUNTIF","accept":["3"]},{"id":"c4","text":"B12 — 8A ұпайларының қосындысы (SUMIF)","cell":"B12","points":2,"fn":"SUMIF","accept":["68"]},{"id":"c5","text":"B13 — 8B орташа ұпайы (AVERAGEIF)","cell":"B13","points":2,"fn":"AVERAGEIF","accept":["21.33"]},{"id":"c6","text":"B14 — екінші ең жоғары ұпай (LARGE)","cell":"B14","points":2,"fn":"LARGE","accept":["25"]}],"ru":{"title":"Практика: результаты олимпиады","prompt":"Введи таблицу с рисунка. Ответы на вопросы найди функциями COUNTIF, SUMIF, AVERAGEIF и LARGE.","picture":"lec/inf8-t34-ru.svg","pictureAlt":"Класс и баллы восьми учеников, ниже пустые ячейки для четырёх вопросов","criteria":[{"id":"c1","text":"Данные введены: A2 = 8A, B2 = 21","cell":"B2","points":1},{"id":"c2","text":"Последняя строка введена: B9 = 26","cell":"B9","points":1},{"id":"c3","text":"B11 — число учеников 8B (COUNTIF)","cell":"B11","points":2,"fn":"COUNTIF"},{"id":"c4","text":"B12 — сумма баллов 8A (SUMIF)","cell":"B12","points":2,"fn":"SUMIF"},{"id":"c5","text":"B13 — средний балл 8B (AVERAGEIF)","cell":"B13","points":2,"fn":"AVERAGEIF"},{"id":"c6","text":"B14 — второй по величине балл (LARGE)","cell":"B14","points":2,"fn":"LARGE"}]},"en":{"title":"Practice: olympiad results","prompt":"Enter the table from the picture. Answer the questions with COUNTIF, SUMIF, AVERAGEIF and LARGE.","picture":"lec/inf8-t34-en.svg","pictureAlt":"Class and points of eight pupils with empty cells for four questions below","criteria":[{"id":"c1","text":"Data entered: A2 = 8A, B2 = 21","cell":"B2","points":1},{"id":"c2","text":"Last row entered: B9 = 26","cell":"B9","points":1},{"id":"c3","text":"B11 — number of 8B pupils (COUNTIF)","cell":"B11","points":2,"fn":"COUNTIF"},{"id":"c4","text":"B12 — total points of 8A (SUMIF)","cell":"B12","points":2,"fn":"SUMIF"},{"id":"c5","text":"B13 — mean points of 8B (AVERAGEIF)","cell":"B13","points":2,"fn":"AVERAGEIF"},{"id":"c6","text":"B14 — the second highest score (LARGE)","cell":"B14","points":2,"fn":"LARGE"}]}},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"COUNTIF","prompt":"A1:A5 ұяшықтарында 2, 5, 3, 8, 4 сандары бар. =COUNTIF(A1:A5;\">3\") нәтижесі қандай?","options":["2","3","4","5"],"answer":1,"explanation":"3-тен үлкен сандар: 5, 8, 4 — барлығы 3.","points":1,"ru":{"title":"COUNTIF","prompt":"В A1:A5 числа 2, 5, 3, 8, 4. Каков результат =COUNTIF(A1:A5;\">3\")?","options":["2","3","4","5"],"explanation":"Больше 3: числа 5, 8, 4 — всего 3."},"en":{"title":"COUNTIF","prompt":"A1:A5 hold 2, 5, 3, 8, 4. What does =COUNTIF(A1:A5;\">3\") give?","options":["2","3","4","5"],"explanation":"Numbers above 3 are 5, 8, 4 — three of them."}}]$sl$::jsonb),
    ($sl$3.5 Деректерді талдау. Практикум$sl$, $sl$Информатика$sl$, 4, $sl${"summary":"Талдау дағдыларын бекіту: IF, COUNTIF, AVERAGEIF, MAX, пайыз. Екі практикалық тапсырма: емтихан нәтижелері және екі қаланың температурасы.","objectives":["Үлкен кестеден сұрақтарға жауап табу","Бірнеше функцияны бір есепте қолдану"],"grade":8,"duration":"45 минут","ru":{"summary":"Закрепление навыков анализа: IF, COUNTIF, AVERAGEIF, MAX, проценты. Два практических задания: результаты экзамена и температура в двух городах.","objectives":["Находить ответы на вопросы по большой таблице","Применять несколько функций в одной задаче"]},"en":{"summary":"Practising analysis: IF, COUNTIF, AVERAGEIF, MAX and percentages. Two tasks: exam results and the temperature in two cities.","objectives":["Answer questions from a larger table","Combine several functions in one problem"]}}$sl$::jsonb, $sl$[{"term":"percentage","definition":"Пайыз — үлестің бүтінге қатынасы × 100 · Процент — отношение части к целому × 100 · Percentage — part ÷ whole × 100"}]$sl$::jsonb, $sl$[{"type":"title","pageType":"slide","templateId":"title","title":"3.5 Деректерді талдау. Практикум","subtitle":"Информатика 8-сынып · 3-тарау «Электрондық кестелер»","ru":{"title":"3.5 Анализ данных. Практикум","subtitle":"Информатика 8 класс · глава 3 «Электронные таблицы»"},"en":{"title":"3.5 Data analysis. Practice","subtitle":"Informatics Grade 8 · Chapter 3 “Spreadsheets”"},"design":"lab"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"Қысқаша ескерту: формулалар","bullets":["Бір ұяшық: IF — шарт бойынша таңдау. Диапазон: SUM, AVERAGE, MAX, MIN, COUNT.","Шартпен: COUNTIF, SUMIF, AVERAGEIF. Орны бойынша: LARGE, SMALL.","Пайыз: үлес ÷ бүтін × 100. Бекітілген ұяшық: $B$2."],"code":"=IF(B2>=50;1;0)\n=COUNTIF(C2:C9;1)\n=B12/COUNT(B2:B9)*100\n=AVERAGEIF(C2:C9;1;B2:B9)","lang":"text","art":"functions","ru":{"title":"Памятка: формулы","bullets":["Одна ячейка: IF — выбор по условию. Диапазон: SUM, AVERAGE, MAX, MIN, COUNT.","С условием: COUNTIF, SUMIF, AVERAGEIF. По месту в ряду: LARGE, SMALL.","Процент: часть ÷ целое × 100. Закреплённая ячейка: $B$2."]},"en":{"title":"Quick reminder: formulas","bullets":["One cell: IF chooses by a condition. Range: SUM, AVERAGE, MAX, MIN, COUNT.","With a condition: COUNTIF, SUMIF, AVERAGEIF. By rank: LARGE, SMALL.","Percentage: part ÷ whole × 100. A pinned cell: $B$2."]},"design":"lab"},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Пайыз","prompt":"20 оқушының 5-еуі «5» алды. Бұл неше пайыз?","options":["5%","15%","25%","40%"],"answer":2,"explanation":"5 ÷ 20 × 100 = 25.","points":1,"ru":{"title":"Процент","prompt":"Из 20 учеников 5 получили «5». Сколько это процентов?","options":["5%","15%","25%","40%"],"explanation":"5 ÷ 20 × 100 = 25."},"en":{"title":"Percentage","prompt":"5 of 20 pupils got a 5. What percentage is that?","options":["5%","15%","25%","40%"],"explanation":"5 ÷ 20 × 100 = 25."}},{"type":"task","pageType":"interactive","templateId":"short-answer","kind":"practice","title":"Практика 1: емтихан нәтижелері","prompt":"Кестені енгіз. IF арқылы «өтті» (1) немесе «өтпеді» (0) белгісін қой, сосын көрсеткіштерді есепте. Өту шегі — 50 ұпай.","points":10,"picture":"lec/inf8-t35a-kk.svg","pictureAlt":"Сегіз оқушының емтихан ұпайлары, өтті/өтпеді бағаны және төрт көрсеткіш үшін бос ұяшықтар","sheet":{"rows":14,"cols":8},"criteria":[{"id":"c1","text":"Деректер енгізілген: B2 = 82 және B9 = 53","cell":"B9","points":1,"accept":["53"]},{"id":"c2","text":"C2 — IF функциясымен (82 ұпай → 1)","cell":"C2","points":1,"fn":"IF","accept":["1"]},{"id":"c3","text":"C6 — IF функциясымен (38 ұпай → 0)","cell":"C6","points":1,"fn":"IF","accept":["0"]},{"id":"c4","text":"B11 — орташа ұпай (AVERAGE)","cell":"B11","points":1,"fn":"AVERAGE","accept":["63"]},{"id":"c5","text":"B12 — өткендер саны (COUNTIF)","cell":"B12","points":2,"fn":"COUNTIF","accept":["6"]},{"id":"c6","text":"B13 — өткендердің үлесі, % (формуламен)","cell":"B13","points":2,"formula":true,"accept":["75"]},{"id":"c7","text":"B14 — өткендердің орташа ұпайы (AVERAGEIF)","cell":"B14","points":2,"fn":"AVERAGEIF","accept":["70.17"]}],"ru":{"title":"Практика 1: результаты экзамена","prompt":"Введи таблицу. Функцией IF поставь «сдал» (1) или «не сдал» (0), затем посчитай показатели. Проходной балл — 50.","picture":"lec/inf8-t35a-ru.svg","pictureAlt":"Баллы восьми учеников, столбец сдал/не сдал и пустые ячейки для четырёх показателей","criteria":[{"id":"c1","text":"Данные введены: B2 = 82 и B9 = 53","cell":"B9","points":1},{"id":"c2","text":"C2 — функцией IF (82 балла → 1)","cell":"C2","points":1,"fn":"IF"},{"id":"c3","text":"C6 — функцией IF (38 баллов → 0)","cell":"C6","points":1,"fn":"IF"},{"id":"c4","text":"B11 — средний балл (AVERAGE)","cell":"B11","points":1,"fn":"AVERAGE"},{"id":"c5","text":"B12 — сколько сдали (COUNTIF)","cell":"B12","points":2,"fn":"COUNTIF"},{"id":"c6","text":"B13 — доля сдавших, % (формулой)","cell":"B13","points":2,"formula":true},{"id":"c7","text":"B14 — средний балл сдавших (AVERAGEIF)","cell":"B14","points":2,"fn":"AVERAGEIF"}]},"en":{"title":"Practice 1: exam results","prompt":"Enter the table. Use IF to mark pass (1) or fail (0), then work out the measures. The pass mark is 50 points.","picture":"lec/inf8-t35a-en.svg","pictureAlt":"Exam scores of eight pupils, a pass/fail column and empty cells for four measures","criteria":[{"id":"c1","text":"Data entered: B2 = 82 and B9 = 53","cell":"B9","points":1},{"id":"c2","text":"C2 — with IF (82 points → 1)","cell":"C2","points":1,"fn":"IF"},{"id":"c3","text":"C6 — with IF (38 points → 0)","cell":"C6","points":1,"fn":"IF"},{"id":"c4","text":"B11 — mean score (AVERAGE)","cell":"B11","points":1,"fn":"AVERAGE"},{"id":"c5","text":"B12 — how many passed (COUNTIF)","cell":"B12","points":2,"fn":"COUNTIF"},{"id":"c6","text":"B13 — share who passed, % (formula)","cell":"B13","points":2,"formula":true},{"id":"c7","text":"B14 — mean score of those who passed (AVERAGEIF)","cell":"B14","points":2,"fn":"AVERAGEIF"}]}},{"type":"task","pageType":"interactive","templateId":"short-answer","kind":"practice","title":"Практика 2: екі қаланың температурасы","prompt":"Кестені енгіз. Күн сайынғы айырманы, орташа температураны, ең жоғары мәнді және 20 °C-тан жылы күндер санын тап.","points":10,"picture":"lec/inf8-t35b-kk.svg","pictureAlt":"Жеті күндегі екі қаланың температурасы, бос ұяшықтар айырма, орташа, максимум және жылы күндер үшін","sheet":{"rows":14,"cols":8},"criteria":[{"id":"c1","text":"Деректер енгізілген: B2 = 18 және C8 = 22","cell":"C8","points":1,"accept":["22"]},{"id":"c2","text":"D2 — айырма (формуламен)","cell":"D2","points":1,"formula":true,"accept":["3"]},{"id":"c3","text":"D8 — айырма теріс болуы мүмкін (формуламен)","cell":"D8","points":1,"formula":true,"accept":["-2"]},{"id":"c4","text":"B9 — А қаласының орташа температурасы","cell":"B9","points":2,"fn":"AVERAGE","accept":["21.29"]},{"id":"c5","text":"C9 — Б қаласының орташа температурасы","cell":"C9","points":2,"fn":"AVERAGE","accept":["18.86"]},{"id":"c6","text":"B10 — А қаласының ең жоғары температурасы (MAX)","cell":"B10","points":1,"fn":"MAX","accept":["25"]},{"id":"c7","text":"B11 — 20 °C-тан жылы күндер саны (COUNTIF)","cell":"B11","points":2,"fn":"COUNTIF","accept":["4"]}],"ru":{"title":"Практика 2: температура в двух городах","prompt":"Введи таблицу. Найди ежедневную разность, средние температуры, наибольшее значение и число дней теплее 20 °C.","picture":"lec/inf8-t35b-ru.svg","pictureAlt":"Температура двух городов за семь дней, пустые ячейки для разности, среднего, максимума и тёплых дней","criteria":[{"id":"c1","text":"Данные введены: B2 = 18 и C8 = 22","cell":"C8","points":1},{"id":"c2","text":"D2 — разность (формулой)","cell":"D2","points":1,"formula":true},{"id":"c3","text":"D8 — разность может быть отрицательной (формулой)","cell":"D8","points":1,"formula":true},{"id":"c4","text":"B9 — средняя температура города А","cell":"B9","points":2,"fn":"AVERAGE"},{"id":"c5","text":"C9 — средняя температура города Б","cell":"C9","points":2,"fn":"AVERAGE"},{"id":"c6","text":"B10 — наибольшая температура города А (MAX)","cell":"B10","points":1,"fn":"MAX"},{"id":"c7","text":"B11 — число дней теплее 20 °C (COUNTIF)","cell":"B11","points":2,"fn":"COUNTIF"}]},"en":{"title":"Practice 2: temperature in two cities","prompt":"Enter the table. Work out the daily difference, the mean temperatures, the highest value and the number of days warmer than 20 °C.","picture":"lec/inf8-t35b-en.svg","pictureAlt":"Temperatures in two cities over seven days with empty cells for the difference, mean, maximum and warm days","criteria":[{"id":"c1","text":"Data entered: B2 = 18 and C8 = 22","cell":"C8","points":1},{"id":"c2","text":"D2 — difference (formula)","cell":"D2","points":1,"formula":true},{"id":"c3","text":"D8 — the difference may be negative (formula)","cell":"D8","points":1,"formula":true},{"id":"c4","text":"B9 — mean temperature of city A","cell":"B9","points":2,"fn":"AVERAGE"},{"id":"c5","text":"C9 — mean temperature of city B","cell":"C9","points":2,"fn":"AVERAGE"},{"id":"c6","text":"B10 — highest temperature of city A (MAX)","cell":"B10","points":1,"fn":"MAX"},{"id":"c7","text":"B11 — number of days above 20 °C (COUNTIF)","cell":"B11","points":2,"fn":"COUNTIF"}]}},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Қорытынды жасау","prompt":"Талдаудың соңғы қадамы қандай?","options":["Деректерді жинау","Сұрақ қою","Нәтижеден қорытынды жазу","Кестені жою"],"answer":2,"explanation":"Сұрақ — бастамасы, қорытынды — соңы: нәтиже сұраққа жауап береді.","points":1,"ru":{"title":"Вывод","prompt":"Какой последний шаг анализа данных?","options":["Сбор данных","Постановка вопроса","Вывод по результату","Удаление таблицы"],"explanation":"Вопрос — начало, вывод — конец: результат отвечает на вопрос."},"en":{"title":"Drawing a conclusion","prompt":"What is the last step of a data analysis?","options":["Collecting the data","Asking the question","Writing a conclusion from the result","Deleting the table"],"explanation":"The question is the start and the conclusion the end: the result answers the question."}}]$sl$::jsonb),
    ($sl$3.6 Электрондық кестемен қолданбалы есептер шығару$sl$, $sl$Информатика$sl$, 5, $sl${"summary":"Күнделікті өмірдің есептері: бюджет, саяхат шығыны, пайыз. Кестелік модель құру.","objectives":["Өмірлік есептің кестелік моделін құру","Бюджет пен шығынды формулалармен есептеу"],"grade":8,"duration":"45 минут","ru":{"summary":"Задачи из жизни: бюджет, расходы на поездку, проценты. Построение табличной модели.","objectives":["Строить табличную модель жизненной задачи","Считать бюджет и расходы формулами"]},"en":{"summary":"Real-life problems: a budget, trip costs, percentages. Building a table model.","objectives":["Build a table model of a real-life problem","Work out a budget and costs with formulas"]}}$sl$::jsonb, $sl$[{"term":"model","definition":"Модель — нақты жағдайдың кестедегі жеңілдетілген көрінісі · Модель — упрощённое описание реальной ситуации в таблице · Model — a simplified description of a real situation in a table"}]$sl$::jsonb, $sl$[{"type":"title","pageType":"slide","templateId":"title","title":"3.6 Электрондық кестемен қолданбалы есептер шығару","subtitle":"Информатика 8-сынып · 3-тарау «Электрондық кестелер»","ru":{"title":"3.6 Решение прикладных задач в электронных таблицах","subtitle":"Информатика 8 класс · глава 3 «Электронные таблицы»"},"en":{"title":"3.6 Solving applied problems using spreadsheets","subtitle":"Informatics Grade 8 · Chapter 3 “Spreadsheets”"},"design":"lab"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"Қолданбалы есеп деген не?","bullets":["Қолданбалы есеп — өмірден алынған есеп: сатып алу, бюджет, жол ақысы, жеңілдік.","Оны кестеде шешу үшін модель құрамыз: деректер, тұрақты шамалар және формулалар.","Тұрақты шамаларды (жеңілдік пайызы, баға) жеке ұяшыққа жазамыз — өзгерткенде барлығы қайта есептеледі."],"art":"wallet","ru":{"title":"Что такое прикладная задача?","bullets":["Прикладная задача взята из жизни: покупка, бюджет, проезд, скидка.","Чтобы решить её в таблице, строим модель: данные, постоянные величины и формулы.","Постоянные величины (процент скидки, цену) пишем в отдельную ячейку — при изменении всё пересчитается."]},"en":{"title":"What is an applied problem?","bullets":["An applied problem comes from real life: shopping, a budget, travel, a discount.","To solve it in a sheet we build a model: data, constants and formulas.","Keep constants (a discount rate, a price) in their own cell — change it and everything recalculates."]},"design":"lab"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"Пайдалы формулалар","bullets":["Санның пайызы: =B2*C2/100 (C2 — пайыз).","Өсім: =B2*(1+C2/100). Жеңілдік: =B2*(1-C2/100).","Біреуіне шаққанда: жалпы шығын ÷ адам саны. Нәтижені ROUND-пен дөңгелектеуге болады."],"code":"=B2*C2/100\n=B2*(1+C2/100)\n=B2*(1-C2/100)\n=ROUND(D6/B3;0)","lang":"text","ru":{"title":"Полезные формулы","bullets":["Процент от числа: =B2*C2/100 (C2 — процент).","Увеличение: =B2*(1+C2/100). Скидка: =B2*(1-C2/100).","На одного: общие расходы ÷ число людей. Результат можно округлить функцией ROUND."]},"en":{"title":"Useful formulas","bullets":["A percentage of a number: =B2*C2/100 (C2 is the percentage).","Increase: =B2*(1+C2/100). Discount: =B2*(1-C2/100).","Per person: total cost ÷ number of people. You can round the result with ROUND."]},"design":"lab"},{"type":"solution","pageType":"slide","templateId":"worked-example","kind":"exampletask","title":"Мысал: көлік шығыны","sections":[{"h":"Шарты","text":"450 км жол, көлік 100 км-ге 8 л бензин жұмсайды, 1 л бензин 190 теңге. Жол қанша тұрады?"},{"h":"Алгоритм (қадамдар)","bullets":["B1 = 450, B2 = 8, B3 = 190 — деректер.","Бензин көлемі: B4 = B1*B2/100.","Құны: B5 = B4*B3."]},{"h":"Шешімі","text":"36 л бензин, құны 36 × 190 = 6840 теңге.","hide":true}],"art":"formula","ru":{"title":"Пример: расход на дорогу","sections":[{"h":"Условие","text":"Дорога 450 км, машина тратит 8 л на 100 км, литр бензина стоит 190 тенге. Сколько стоит поездка?"},{"h":"Алгоритм (шаги)","bullets":["B1 = 450, B2 = 8, B3 = 190 — данные.","Объём бензина: B4 = B1*B2/100.","Стоимость: B5 = B4*B3."]},{"h":"Решение","text":"36 л бензина, стоимость 36 × 190 = 6840 тенге.","hide":true}]},"en":{"title":"Example: travel costs","sections":[{"h":"Task","text":"A 450 km trip, the car uses 8 L per 100 km and a litre costs 190 tenge. How much does the trip cost?"},{"h":"Steps","bullets":["B1 = 450, B2 = 8, B3 = 190 are the data.","Fuel volume: B4 = B1*B2/100.","Cost: B5 = B4*B3."]},{"h":"Solution","text":"36 L of petrol, costing 36 × 190 = 6840 tenge.","hide":true}]},"design":"lab"},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Пайыз","prompt":"2000 теңгенің 15%-ы қанша?","options":["150","300","1700","3000"],"answer":1,"explanation":"2000 × 15 ÷ 100 = 300.","points":1,"ru":{"title":"Процент","prompt":"Сколько составляют 15% от 2000 тенге?","options":["150","300","1700","3000"],"explanation":"2000 × 15 ÷ 100 = 300."},"en":{"title":"Percentage","prompt":"What is 15% of 2000 tenge?","options":["150","300","1700","3000"],"explanation":"2000 × 15 ÷ 100 = 300."}},{"type":"task","pageType":"interactive","templateId":"short-answer","kind":"practice","title":"Практика: сынып сапарының бюджеті","prompt":"Суреттегі бюджетті енгіз. Әр баптың құнын, жалпы шығынды, бір оқушыға шаққанды және 10% қор қосылған соманы есепте.","points":11,"picture":"lec/inf8-t36-kk.svg","pictureAlt":"Төрт бап: автобус, музей билеті, түскі ас, сақтандыру; бос ұяшықтар құн, жалпы шығын, бір оқушыға және қор үшін","sheet":{"rows":14,"cols":8},"criteria":[{"id":"c1","text":"Деректер енгізілген: C2 = 36000 және C5 = 200","cell":"C2","points":1,"accept":["36000"]},{"id":"c2","text":"D3 — музей билеттерінің құны (формуламен)","cell":"D3","points":1,"formula":true,"accept":["19200"]},{"id":"c3","text":"D4 — түскі астың құны (формуламен)","cell":"D4","points":1,"formula":true,"accept":["36000"]},{"id":"c4","text":"D6 — жалпы шығын (SUM)","cell":"D6","points":2,"fn":"SUM","accept":["96000"]},{"id":"c5","text":"D8 — бір оқушыға шаққандағы шығын (формуламен)","cell":"D8","points":2,"formula":true,"accept":["4000"]},{"id":"c6","text":"D9 — 10% қор қосылған жалпы сома (формуламен)","cell":"D9","points":2,"formula":true,"accept":["105600"]},{"id":"c7","text":"D10 — қормен бір оқушыға (формуламен)","cell":"D10","points":2,"formula":true,"accept":["4400"]}],"ru":{"title":"Практика: бюджет поездки класса","prompt":"Введи бюджет с рисунка. Посчитай стоимость каждой статьи, общие расходы, расход на одного ученика и сумму с резервом 10%.","picture":"lec/inf8-t36-ru.svg","pictureAlt":"Четыре статьи: автобус, билет, обед, страховка; пустые ячейки для стоимости, суммы, расхода на одного и резерва","criteria":[{"id":"c1","text":"Данные введены: C2 = 36000 и C5 = 200","cell":"C2","points":1},{"id":"c2","text":"D3 — стоимость билетов в музей (формулой)","cell":"D3","points":1,"formula":true},{"id":"c3","text":"D4 — стоимость обедов (формулой)","cell":"D4","points":1,"formula":true},{"id":"c4","text":"D6 — общие расходы (SUM)","cell":"D6","points":2,"fn":"SUM"},{"id":"c5","text":"D8 — расход на одного ученика (формулой)","cell":"D8","points":2,"formula":true},{"id":"c6","text":"D9 — общая сумма с резервом 10% (формулой)","cell":"D9","points":2,"formula":true},{"id":"c7","text":"D10 — с резервом на одного (формулой)","cell":"D10","points":2,"formula":true}]},"en":{"title":"Practice: a class trip budget","prompt":"Enter the budget from the picture. Work out each item’s cost, the total, the cost per pupil and the total with a 10% reserve.","picture":"lec/inf8-t36-en.svg","pictureAlt":"Four items: bus, museum ticket, lunch, insurance; empty cells for cost, total, per pupil and reserve","criteria":[{"id":"c1","text":"Data entered: C2 = 36000 and C5 = 200","cell":"C2","points":1},{"id":"c2","text":"D3 — cost of museum tickets (formula)","cell":"D3","points":1,"formula":true},{"id":"c3","text":"D4 — cost of lunches (formula)","cell":"D4","points":1,"formula":true},{"id":"c4","text":"D6 — total cost (SUM)","cell":"D6","points":2,"fn":"SUM"},{"id":"c5","text":"D8 — cost per pupil (formula)","cell":"D8","points":2,"formula":true},{"id":"c6","text":"D9 — total with a 10% reserve (formula)","cell":"D9","points":2,"formula":true},{"id":"c7","text":"D10 — per pupil with the reserve (formula)","cell":"D10","points":2,"formula":true}]}},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Тұрақты шама","prompt":"Жеңілдік пайызын неге жеке ұяшыққа жазған дұрыс?","options":["Кесте әдемі болады","Пайызды өзгертсек, барлық нәтиже өздігінен қайта есептеледі","Формула қысқа болады, бірақ нәтиже өзгермейді","Бұлай жасауға болмайды"],"answer":1,"explanation":"Модельдің басты артықшылығы — деректерді өзгертіп, жаңа нәтижені бірден көру.","points":1,"ru":{"title":"Постоянная величина","prompt":"Почему процент скидки лучше записать в отдельную ячейку?","options":["Таблица красивее","Если изменить процент, все результаты пересчитаются сами","Формула короче, но результат не меняется","Так делать нельзя"],"explanation":"Главное достоинство модели — изменить данные и сразу увидеть новый результат."},"en":{"title":"A constant","prompt":"Why is it better to keep the discount rate in its own cell?","options":["The table looks nicer","Change the rate and all the results recalculate","The formula is shorter but the result never changes","You are not allowed to do this"],"explanation":"The great strength of a model: change the data and see the new result at once."}}]$sl$::jsonb),
    ($sl$3.7 Қолданбалы есептер шығару. II бөлім$sl$, $sl$Информатика$sl$, 6, $sl${"summary":"Күрделірек қолданбалы есептер: еңбекақы, қосымша ақы, салық, ішкі IF және баға қою.","objectives":["Күрделі есептерді кезеңдерге бөлу","Ішкі IF қолдану"],"grade":8,"duration":"45 минут","ru":{"summary":"Более сложные прикладные задачи: зарплата, надбавка, налог, вложенный IF и выставление оценок.","objectives":["Разбивать сложные задачи на этапы","Использовать вложенный IF"]},"en":{"summary":"Harder applied problems: pay, bonus, tax, nested IF and converting scores to marks.","objectives":["Split a complex problem into stages","Use a nested IF"]}}$sl$::jsonb, $sl$[{"term":"nested IF","definition":"Ішкі IF — IF ішіне жазылған IF, бірнеше шарт тексеру үшін · Вложенный IF — IF внутри IF для проверки нескольких условий · Nested IF — an IF inside another IF to test several conditions"}]$sl$::jsonb, $sl$[{"type":"title","pageType":"slide","templateId":"title","title":"3.7 Қолданбалы есептер шығару. II бөлім","subtitle":"Информатика 8-сынып · 3-тарау «Электрондық кестелер»","ru":{"title":"3.7 Прикладные задачи. Часть II","subtitle":"Информатика 8 класс · глава 3 «Электронные таблицы»"},"en":{"title":"3.7 Solving applied problems using spreadsheets. Part II","subtitle":"Informatics Grade 8 · Chapter 3 “Spreadsheets”"},"design":"lab"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"Күрделі есепті бөліктерге бөлу","bullets":["Алдымен әр бағанның не екенін ата: бастапқы деректер, аралық нәтиже, соңғы жауап.","Бағандарды солдан оңға қарай толтыр: әр келесі баған алдыңғыларға сүйенеді.","Бірінші жолды тексерген соң ғана формуланы төмен көшір."],"art":"steps","ru":{"title":"Разбиваем сложную задачу на части","bullets":["Сначала назови, чем является каждый столбец: исходные данные, промежуточный результат, ответ.","Заполняй столбцы слева направо: каждый следующий опирается на предыдущие.","Копируй формулу вниз только после проверки первой строки."]},"en":{"title":"Splitting a complex problem","bullets":["First name each column: input data, intermediate result, final answer.","Fill the columns from left to right: each one builds on the ones before.","Copy a formula down only after checking the first row."]},"design":"lab"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"Ішкі IF","bullets":["Екіден көп нұсқа болса, IF-тің үшінші аргументіне тағы бір IF жазамыз.","Мысал: бағаны ұпай бойынша қою — 85-тен 5, 65-тен 4, 50-ден 3, басқа жағдайда 2.","Шарттарды үлкеннен кішіге қарай жаз. Жақшаларды санап, соңында тең жабу керек."],"code":"=IF(B2>=85;5;\n IF(B2>=65;4;\n  IF(B2>=50;3;2)))","lang":"text","art":"ifflow","ru":{"title":"Вложенный IF","bullets":["Если вариантов больше двух, в третий аргумент IF вкладывают ещё один IF.","Пример: оценка по баллам — от 85 пятёрка, от 65 четвёрка, от 50 тройка, иначе 2.","Условия пиши от большего к меньшему. Считай скобки: в конце их нужно закрыть поровну."]},"en":{"title":"Nested IF","bullets":["With more than two outcomes, put another IF in the third argument.","Example: marks from scores — 85+ gives 5, 65+ gives 4, 50+ gives 3, otherwise 2.","Write the conditions from the largest to the smallest. Count the brackets: close as many as you opened."]},"design":"lab"},{"type":"solution","pageType":"slide","templateId":"worked-example","kind":"exampletask","title":"Мысал: еңбекақы","sections":[{"h":"Шарты","text":"Қызметкердің айлығы 150000, ал стажы 6 жыл. Стаж 5 жылдан көп болса, қосымша ақы 20%, әйтпесе 10%. Қосымша ақыны тап."},{"h":"Алгоритм (қадамдар)","bullets":["B2 = 150000, C2 = 6 — деректер.","Шарт: C2>=5.","D2 = IF(C2>=5;B2*0.2;B2*0.1)."]},{"h":"Шешімі","text":"Стаж 6 ≥ 5, сондықтан қосымша ақы 150000 × 0,2 = 30000.","hide":true}],"art":"salary","ru":{"title":"Пример: зарплата","sections":[{"h":"Условие","text":"Оклад работника 150000, стаж 6 лет. Если стаж не меньше 5 лет, надбавка 20%, иначе 10%. Найди надбавку."},{"h":"Алгоритм (шаги)","bullets":["B2 = 150000, C2 = 6 — данные.","Условие: C2>=5.","D2 = IF(C2>=5;B2*0.2;B2*0.1)."]},{"h":"Решение","text":"Стаж 6 ≥ 5, поэтому надбавка 150000 × 0,2 = 30000.","hide":true}]},"en":{"title":"Example: pay","sections":[{"h":"Task","text":"An employee earns 150000 with 6 years of service. With 5 or more years the bonus is 20%, otherwise 10%. Find the bonus."},{"h":"Steps","bullets":["B2 = 150000, C2 = 6 are the data.","Condition: C2>=5.","D2 = IF(C2>=5;B2*0.2;B2*0.1)."]},{"h":"Solution","text":"6 ≥ 5, so the bonus is 150000 × 0.2 = 30000.","hide":true}]},"design":"lab"},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Ішкі IF","prompt":"B2 ұяшығында 70 бар. =IF(B2>=85;5;IF(B2>=65;4;IF(B2>=50;3;2))) нәтижесі қандай?","options":["5","4","3","2"],"answer":1,"explanation":"70 ≥ 85 — жалған, 70 ≥ 65 — рас, сондықтан 4.","points":1,"ru":{"title":"Вложенный IF","prompt":"В B2 число 70. Каков результат =IF(B2>=85;5;IF(B2>=65;4;IF(B2>=50;3;2)))?","options":["5","4","3","2"],"explanation":"70 ≥ 85 — ложь, 70 ≥ 65 — истина, значит 4."},"en":{"title":"Nested IF","prompt":"B2 holds 70. What does =IF(B2>=85;5;IF(B2>=65;4;IF(B2>=50;3;2))) return?","options":["5","4","3","2"],"explanation":"70 ≥ 85 is false, 70 ≥ 65 is true, so 4."}},{"type":"task","pageType":"interactive","templateId":"short-answer","kind":"practice","title":"Практика 1: еңбекақы кестесі","prompt":"Кестені енгіз. Қосымша ақыны IF-пен тап, жалпы соманы, 10% салықты және қолға тиетін соманы есепте.","points":10,"picture":"lec/inf8-t37a-kk.svg","pictureAlt":"Төрт қызметкердің айлығы мен стажы, бос ұяшықтар қосымша ақы, барлығы, салық және қолға тиетін сома үшін","sheet":{"rows":14,"cols":8},"criteria":[{"id":"c1","text":"Деректер енгізілген: B2 = 150000 және C5 = 1","cell":"C5","points":1,"accept":["1"]},{"id":"c2","text":"D2 — Айгүлдің қосымша ақысы (IF)","cell":"D2","points":2,"fn":"IF","accept":["30000"]},{"id":"c3","text":"D3 — Болаттың қосымша ақысы (IF)","cell":"D3","points":2,"fn":"IF","accept":["12000"]},{"id":"c4","text":"E4 — Даналың жалпы сомасы (формуламен)","cell":"E4","points":1,"formula":true,"accept":["216000"]},{"id":"c5","text":"F4 — Даналың салығы (формуламен)","cell":"F4","points":1,"formula":true,"accept":["21600"]},{"id":"c6","text":"G5 — Ерланның қолға тиетін сомасы (формуламен)","cell":"G5","points":1,"formula":true,"accept":["99000"]},{"id":"c7","text":"G6 — барлық қолға тиетін соманың қосындысы (SUM)","cell":"G6","points":2,"fn":"SUM","accept":["574200"]}],"ru":{"title":"Практика 1: ведомость зарплаты","prompt":"Введи таблицу. Надбавку найди с IF, затем посчитай общую сумму, налог 10% и сумму на руки.","picture":"lec/inf8-t37a-ru.svg","pictureAlt":"Оклад и стаж четырёх работников, пустые ячейки для надбавки, итога, налога и суммы на руки","criteria":[{"id":"c1","text":"Данные введены: B2 = 150000 и C5 = 1","cell":"C5","points":1},{"id":"c2","text":"D2 — надбавка Айгуль (IF)","cell":"D2","points":2,"fn":"IF"},{"id":"c3","text":"D3 — надбавка Болата (IF)","cell":"D3","points":2,"fn":"IF"},{"id":"c4","text":"E4 — итого у Даны (формулой)","cell":"E4","points":1,"formula":true},{"id":"c5","text":"F4 — налог Даны (формулой)","cell":"F4","points":1,"formula":true},{"id":"c6","text":"G5 — сумма на руки у Ерлана (формулой)","cell":"G5","points":1,"formula":true},{"id":"c7","text":"G6 — сумма всех выплат на руки (SUM)","cell":"G6","points":2,"fn":"SUM"}]},"en":{"title":"Practice 1: a pay sheet","prompt":"Enter the table. Find the bonus with IF, then work out the total, the 10% tax and the take-home pay.","picture":"lec/inf8-t37a-en.svg","pictureAlt":"Salary and years of four employees with empty cells for the bonus, total, tax and net pay","criteria":[{"id":"c1","text":"Data entered: B2 = 150000 and C5 = 1","cell":"C5","points":1},{"id":"c2","text":"D2 — Aigul’s bonus (IF)","cell":"D2","points":2,"fn":"IF"},{"id":"c3","text":"D3 — Bolat’s bonus (IF)","cell":"D3","points":2,"fn":"IF"},{"id":"c4","text":"E4 — Dana’s total (formula)","cell":"E4","points":1,"formula":true},{"id":"c5","text":"F4 — Dana’s tax (formula)","cell":"F4","points":1,"formula":true},{"id":"c6","text":"G5 — Erlan’s net pay (formula)","cell":"G5","points":1,"formula":true},{"id":"c7","text":"G6 — sum of all net pay (SUM)","cell":"G6","points":2,"fn":"SUM"}]}},{"type":"task","pageType":"interactive","templateId":"short-answer","kind":"practice","title":"Практика 2: ұпайдан баға","prompt":"Кестені енгіз. Ішкі IF-пен ұпайды бағаға айналдыр (85-тен 5, 65-тен 4, 50-ден 3, әйтпесе 2), сосын жалпы көрсеткіштерді тап.","points":11,"picture":"lec/inf8-t37b-kk.svg","pictureAlt":"Алты оқушының ұпайы, баға бағаны және үш көрсеткіш үшін бос ұяшықтар","sheet":{"rows":14,"cols":8},"criteria":[{"id":"c1","text":"Деректер енгізілген: B2 = 92 және B7 = 85","cell":"B7","points":1,"accept":["85"]},{"id":"c2","text":"C2 — ішкі IF (92 ұпай → 5)","cell":"C2","points":2,"fn":"IF","accept":["5"]},{"id":"c3","text":"C4 — ішкі IF (55 ұпай → 3)","cell":"C4","points":2,"fn":"IF","accept":["3"]},{"id":"c4","text":"C5 — ішкі IF (40 ұпай → 2)","cell":"C5","points":2,"fn":"IF","accept":["2"]},{"id":"c5","text":"B9 — орташа ұпай (AVERAGE)","cell":"B9","points":1,"fn":"AVERAGE","accept":["69.5"]},{"id":"c6","text":"B10 — 4 және 5 бағалардың саны (COUNTIF)","cell":"B10","points":2,"fn":"COUNTIF","accept":["4"]},{"id":"c7","text":"B11 — орташа баға (AVERAGE)","cell":"B11","points":1,"fn":"AVERAGE","accept":["3.83"]}],"ru":{"title":"Практика 2: баллы в оценки","prompt":"Введи таблицу. Вложенным IF переведи баллы в оценки (от 85 — 5, от 65 — 4, от 50 — 3, иначе 2), затем найди общие показатели.","picture":"lec/inf8-t37b-ru.svg","pictureAlt":"Баллы шести учеников, столбец оценок и пустые ячейки для трёх показателей","criteria":[{"id":"c1","text":"Данные введены: B2 = 92 и B7 = 85","cell":"B7","points":1},{"id":"c2","text":"C2 — вложенный IF (92 балла → 5)","cell":"C2","points":2,"fn":"IF"},{"id":"c3","text":"C4 — вложенный IF (55 баллов → 3)","cell":"C4","points":2,"fn":"IF"},{"id":"c4","text":"C5 — вложенный IF (40 баллов → 2)","cell":"C5","points":2,"fn":"IF"},{"id":"c5","text":"B9 — средний балл (AVERAGE)","cell":"B9","points":1,"fn":"AVERAGE"},{"id":"c6","text":"B10 — число оценок 4 и 5 (COUNTIF)","cell":"B10","points":2,"fn":"COUNTIF"},{"id":"c7","text":"B11 — средняя оценка (AVERAGE)","cell":"B11","points":1,"fn":"AVERAGE"}]},"en":{"title":"Practice 2: scores to marks","prompt":"Enter the table. With a nested IF turn scores into marks (85+ is 5, 65+ is 4, 50+ is 3, otherwise 2), then find the overall measures.","picture":"lec/inf8-t37b-en.svg","pictureAlt":"Scores of six pupils, a column of marks and empty cells for three measures","criteria":[{"id":"c1","text":"Data entered: B2 = 92 and B7 = 85","cell":"B7","points":1},{"id":"c2","text":"C2 — nested IF (92 points → 5)","cell":"C2","points":2,"fn":"IF"},{"id":"c3","text":"C4 — nested IF (55 points → 3)","cell":"C4","points":2,"fn":"IF"},{"id":"c4","text":"C5 — nested IF (40 points → 2)","cell":"C5","points":2,"fn":"IF"},{"id":"c5","text":"B9 — mean score (AVERAGE)","cell":"B9","points":1,"fn":"AVERAGE"},{"id":"c6","text":"B10 — number of marks 4 and 5 (COUNTIF)","cell":"B10","points":2,"fn":"COUNTIF"},{"id":"c7","text":"B11 — mean mark (AVERAGE)","cell":"B11","points":1,"fn":"AVERAGE"}]}},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Қорытынды","prompt":"Күрделі есепті кестеде шешуді қайдан бастаған дұрыс?","options":["Бірден ең соңғы формуладан","Бағандардың рөлін анықтап, деректерді енгізуден","Диаграмма салудан","Кестені басып шығарудан"],"answer":1,"explanation":"Алдымен құрылым мен деректер, сосын формулалар.","points":1,"ru":{"title":"Итог","prompt":"С чего лучше начать решение сложной задачи в таблице?","options":["Сразу с последней формулы","С выяснения роли столбцов и ввода данных","С построения диаграммы","С печати таблицы"],"explanation":"Сначала структура и данные, потом формулы."},"en":{"title":"Summary","prompt":"Where is it best to start solving a complex problem in a sheet?","options":["From the very last formula","By working out each column’s role and entering the data","By drawing a chart","By printing the table"],"explanation":"Structure and data first, formulas after."}}]$sl$::jsonb),
    ($sl$Өзіңді тексер$sl$, $sl$Информатика$sl$, 7, $sl${"summary":"3-тарауды қорытындылау: статистика, функциялар, IF, шартты функциялар, диаграммалар, абсолютті сілтеме. Тест және қорытынды практика.","objectives":["3-тарау тақырыптарын қайталау","Өз біліміңді бағалау"],"grade":8,"duration":"45 минут","ru":{"summary":"Итог главы 3: статистика, функции, IF, функции с условием, диаграммы, абсолютные ссылки. Тест и итоговая практика.","objectives":["Повторить темы главы 3","Оценить свои знания"]},"en":{"summary":"Wrapping up chapter 3: statistics, functions, IF, conditional functions, charts, absolute references. A test and a final task.","objectives":["Revise chapter 3","Check what you know"]}}$sl$::jsonb, $sl$[]$sl$::jsonb, $sl$[{"type":"title","pageType":"slide","templateId":"title","title":"Өзіңді тексер","subtitle":"Информатика 8-сынып · 3-тарау «Электрондық кестелер»","ru":{"title":"Проверь себя","subtitle":"Информатика 8 класс · глава 3 «Электронные таблицы»"},"en":{"title":"Check yourself","subtitle":"Informatics Grade 8 · Chapter 3 “Spreadsheets”"},"design":"lab"},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Орташа мән","prompt":"4, 6, 8, 10 сандарының орташа мәні қандай?","options":["6","7","8","28"],"answer":1,"explanation":"(4+6+8+10) ÷ 4 = 28 ÷ 4 = 7.","points":1,"ru":{"title":"Среднее","prompt":"Чему равно среднее чисел 4, 6, 8, 10?","options":["6","7","8","28"],"explanation":"(4+6+8+10) ÷ 4 = 28 ÷ 4 = 7."},"en":{"title":"Mean","prompt":"What is the mean of 4, 6, 8, 10?","options":["6","7","8","28"],"explanation":"(4+6+8+10) ÷ 4 = 28 ÷ 4 = 7."}},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Диапазон","prompt":"B2:B9 диапазонында неше ұяшық бар?","options":["7","8","9","2"],"answer":1,"explanation":"B2, B3, …, B9: 9 − 2 + 1 = 8 ұяшық.","points":1,"ru":{"title":"Диапазон","prompt":"Сколько ячеек в диапазоне B2:B9?","options":["7","8","9","2"],"explanation":"B2, B3, …, B9: 9 − 2 + 1 = 8 ячеек."},"en":{"title":"Range","prompt":"How many cells are in the range B2:B9?","options":["7","8","9","2"],"explanation":"B2, B3, …, B9: 9 − 2 + 1 = 8 cells."}},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Формула жазылуы","prompt":"Қай жазба дұрыс формула?","options":["SUM(B2:B6)","=SUM(B2:B6)","SUM B2:B6","\"SUM\"(B2:B6)"],"answer":1,"explanation":"Формула әрқашан «=» белгісінен басталады.","points":1,"ru":{"title":"Запись формулы","prompt":"Какая запись является формулой?","options":["SUM(B2:B6)","=SUM(B2:B6)","SUM B2:B6","\"SUM\"(B2:B6)"],"explanation":"Формула всегда начинается со знака «=»."},"en":{"title":"Writing a formula","prompt":"Which entry is a formula?","options":["SUM(B2:B6)","=SUM(B2:B6)","SUM B2:B6","\"SUM\"(B2:B6)"],"explanation":"A formula always begins with “=”."}},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Шартты функция","prompt":"A1:A6 ұяшықтарында 8A, 8B, 8A, 8C, 8A, 8B бар. =COUNTIF(A1:A6;\"8A\") нәтижесі қандай?","options":["2","3","4","6"],"answer":1,"explanation":"8A үш рет кездеседі.","points":1,"ru":{"title":"Функция с условием","prompt":"В A1:A6: 8A, 8B, 8A, 8C, 8A, 8B. Чему равно =COUNTIF(A1:A6;\"8A\")?","options":["2","3","4","6"],"explanation":"8A встречается три раза."},"en":{"title":"Conditional function","prompt":"A1:A6 hold 8A, 8B, 8A, 8C, 8A, 8B. What does =COUNTIF(A1:A6;\"8A\") give?","options":["2","3","4","6"],"explanation":"8A occurs three times."}},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Абсолютті сілтеме","prompt":"=B2*$B$8 формуласын төмен көшіргенде не өзгереді?","options":["B2 және $B$8","Тек B2 (B3, B4…)","Тек $B$8","Ештеңе"],"answer":1,"explanation":"$B$8 бекітілген, ал B2 жол бойынша ілгерілейді.","points":1,"ru":{"title":"Абсолютная ссылка","prompt":"Что изменится при копировании формулы =B2*$B$8 вниз?","options":["B2 и $B$8","Только B2 (B3, B4…)","Только $B$8","Ничего"],"explanation":"$B$8 закреплена, а B2 сдвигается по строкам."},"en":{"title":"Absolute reference","prompt":"What changes when =B2*$B$8 is copied down?","options":["Both B2 and $B$8","Only B2 (B3, B4…)","Only $B$8","Nothing"],"explanation":"$B$8 is pinned while B2 moves down the rows."}},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Диаграмма","prompt":"Бір аптадағы температураның өзгерісін көрсету үшін қай диаграмма қолайлы?","options":["Дөңгелек","Сызықты","Тек кесте","Ешқайсысы"],"answer":1,"explanation":"Уақыт бойынша өзгерісті сызықты диаграмма жақсы көрсетеді.","points":1,"ru":{"title":"Диаграмма","prompt":"Какая диаграмма удобна, чтобы показать изменение температуры за неделю?","options":["Круговая","Линейный график","Только таблица","Никакая"],"explanation":"Изменение во времени лучше всего показывает линейный график."},"en":{"title":"Charts","prompt":"Which chart suits showing how the temperature changed over a week?","options":["Pie","Line","Only a table","None of them"],"explanation":"A line chart shows change over time best."}},{"type":"task","pageType":"interactive","templateId":"short-answer","kind":"practice","title":"Қорытынды практика: кітапхана","prompt":"Кестені енгіз. Қосындыны, орташаны, ең үлкен және ең кіші мәнді тап. Әр айдың орташадан жоғары екенін IF-пен белгіле (1 немесе 0), сосын осындай айлардың санын есепте.","points":10,"picture":"lec/inf8-t38-kk.svg","pictureAlt":"Алты айда берілген кітаптар саны, бос ұяшықтар қосынды, орташа, ең үлкен, ең кіші және IF бағаны үшін","sheet":{"rows":14,"cols":8},"criteria":[{"id":"c1","text":"Деректер енгізілген: B2 = 120 және B7 = 145","cell":"B7","points":1,"accept":["145"]},{"id":"c2","text":"B9 — қосынды (SUM)","cell":"B9","points":1,"fn":"SUM","accept":["750"]},{"id":"c3","text":"B10 — орташа (AVERAGE)","cell":"B10","points":1,"fn":"AVERAGE","accept":["125"]},{"id":"c4","text":"B11 — ең үлкен мән (MAX)","cell":"B11","points":1,"fn":"MAX","accept":["150"]},{"id":"c5","text":"B12 — ең кіші мән (MIN)","cell":"B12","points":1,"fn":"MIN","accept":["90"]},{"id":"c6","text":"C3 — IF және B10 бекітілген сілтемесі ($B$10)","cell":"C3","points":2,"fn":"IF","accept":["1"]},{"id":"c7","text":"C4 — IF (90 орташадан аз → 0)","cell":"C4","points":1,"fn":"IF","accept":["0"]},{"id":"c8","text":"B13 — орташадан көп айлардың саны","cell":"B13","points":2,"formula":true,"accept":["3"]}],"ru":{"title":"Итоговая практика: библиотека","prompt":"Введи таблицу. Найди сумму, среднее, наибольшее и наименьшее. Функцией IF отметь, выше ли среднего каждый месяц (1 или 0), затем посчитай таких месяцев.","picture":"lec/inf8-t38-ru.svg","pictureAlt":"Выдано книг за шесть месяцев, пустые ячейки для суммы, среднего, максимума, минимума и столбца IF","criteria":[{"id":"c1","text":"Данные введены: B2 = 120 и B7 = 145","cell":"B7","points":1},{"id":"c2","text":"B9 — сумма (SUM)","cell":"B9","points":1,"fn":"SUM"},{"id":"c3","text":"B10 — среднее (AVERAGE)","cell":"B10","points":1,"fn":"AVERAGE"},{"id":"c4","text":"B11 — наибольшее значение (MAX)","cell":"B11","points":1,"fn":"MAX"},{"id":"c5","text":"B12 — наименьшее значение (MIN)","cell":"B12","points":1,"fn":"MIN"},{"id":"c6","text":"C3 — IF и закреплённая ссылка на B10 ($B$10)","cell":"C3","points":2,"fn":"IF"},{"id":"c7","text":"C4 — IF (90 меньше среднего → 0)","cell":"C4","points":1,"fn":"IF"},{"id":"c8","text":"B13 — число месяцев выше среднего","cell":"B13","points":2,"formula":true}]},"en":{"title":"Final task: the library","prompt":"Enter the table. Find the sum, mean, largest and smallest. Use IF to mark whether each month is above the mean (1 or 0), then count such months.","picture":"lec/inf8-t38-en.svg","pictureAlt":"Books lent over six months with empty cells for the sum, mean, largest, smallest and the IF column","criteria":[{"id":"c1","text":"Data entered: B2 = 120 and B7 = 145","cell":"B7","points":1},{"id":"c2","text":"B9 — the sum (SUM)","cell":"B9","points":1,"fn":"SUM"},{"id":"c3","text":"B10 — the mean (AVERAGE)","cell":"B10","points":1,"fn":"AVERAGE"},{"id":"c4","text":"B11 — the largest value (MAX)","cell":"B11","points":1,"fn":"MAX"},{"id":"c5","text":"B12 — the smallest value (MIN)","cell":"B12","points":1,"fn":"MIN"},{"id":"c6","text":"C3 — IF with the pinned reference to B10 ($B$10)","cell":"C3","points":2,"fn":"IF"},{"id":"c7","text":"C4 — IF (90 is below the mean → 0)","cell":"C4","points":1,"fn":"IF"},{"id":"c8","text":"B13 — the number of months above the mean","cell":"B13","points":2,"formula":true}]}},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"Не үйрендік?","bullets":["Статистика: орташа, медиана, мода, аралық — AVERAGE, MEDIAN, MODE, MAX−MIN.","Функциялар мен формулалар: SUM, COUNT, ROUND, IF, $ сілтеме.","Талдау: COUNTIF, SUMIF, AVERAGEIF, LARGE, SMALL және дұрыс диаграмма.","Қолданбалы есептер: модель құру, тұрақты ұяшық, ішкі IF."],"art":"hero","ru":{"title":"Чему мы научились?","bullets":["Статистика: среднее, медиана, мода, размах — AVERAGE, MEDIAN, MODE, MAX−MIN.","Функции и формулы: SUM, COUNT, ROUND, IF, ссылка с $.","Анализ: COUNTIF, SUMIF, AVERAGEIF, LARGE, SMALL и подходящая диаграмма.","Прикладные задачи: модель, ячейка-константа, вложенный IF."]},"en":{"title":"What did we learn?","bullets":["Statistics: mean, median, mode, range — AVERAGE, MEDIAN, MODE, MAX−MIN.","Functions and formulas: SUM, COUNT, ROUND, IF, the $ reference.","Analysis: COUNTIF, SUMIF, AVERAGEIF, LARGE, SMALL and the right chart.","Applied problems: a model, a constant cell, nested IF."]},"design":"lab"}]$sl$::jsonb)
  ) as t(title, subject, position, plan, terms, slides)
  loop
    select cl.lesson_id into v_lesson from public.cf_curr_lessons cl where cl.module_id = v_module and cl.position = v_spec.position limit 1;
    if v_lesson is null then select id into v_lesson from public.cf_lessons where school_id = v_school and title = v_spec.title limit 1; end if;
    if v_lesson is null then
      insert into public.cf_lessons (school_id, owner_id, title, subject, plan, slides, terms)
      values (v_school, v_owner, v_spec.title, v_spec.subject, v_spec.plan, v_spec.slides, v_spec.terms) returning id into v_lesson;
    else
      update public.cf_lessons set title = v_spec.title, subject = v_spec.subject, plan = v_spec.plan, slides = v_spec.slides, terms = v_spec.terms, updated_at = now() where id = v_lesson;
    end if;
    insert into public.cf_curr_lessons (lesson_id, module_id, position) values (v_lesson, v_module, v_spec.position)
    on conflict (lesson_id) do update set module_id = excluded.module_id, position = excluded.position;
    v_lesson := null;
  end loop;
end;
